function numericOrDefault(value, fallback) {
  const number = typeof value === "number" ? value : Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function finiteNumberOrNull(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function clampNumber(value, min, max) {
  const safeMin = finiteNumberOrNull(min);
  const safeMax = finiteNumberOrNull(max);
  const lower = safeMin === null ? 0 : safeMin;
  const upper =
    safeMax === null ? Number.POSITIVE_INFINITY : Math.max(lower, safeMax);
  return Math.min(Math.max(Number(value) || 0, lower), upper);
}

function showBulletPropertyNotice(message, options) {
  const showNotice = options && options.showNotice;
  const duration =
    options && Number.isFinite(Number(options.duration))
      ? Number(options.duration)
      : null;
  if (typeof showNotice === "function") {
    if (duration === null) {
      showNotice(message);
    } else {
      showNotice(message, duration);
    }
    return;
  }

  if (duration === null) {
    new Notice(message);
  } else {
    new Notice(message, duration);
  }
}

function requireOptionalNodeModule(name) {
  try {
    if (typeof require !== "function") {
      return null;
    }

    return require(name);
  } catch (error) {
    return null;
  }
}

function trimPathSlashes(path, side) {
  const text = String(path || "");
  if (side === "left") {
    return text.replace(/^\/+/, "");
  }

  if (side === "right") {
    return text.replace(/\/+$/, "");
  }

  return text.replace(/^\/+|\/+$/g, "");
}

function joinPathSegments(firstSegment, ...restSegments) {
  const first = trimPathSlashes(firstSegment, "right");
  const rest = restSegments
    .map((segment) => trimPathSlashes(segment, "both"))
    .filter((segment) => segment.length > 0);

  return [first, ...rest].filter((segment) => segment.length > 0).join("/");
}

function getBulletPropertyHomeDir(osModule, env) {
  if (osModule && typeof osModule.homedir === "function") {
    const home = osModule.homedir();
    if (typeof home === "string" && home.trim()) {
      return home;
    }
  }

  if (env && typeof env.HOME === "string" && env.HOME.trim()) {
    return env.HOME;
  }

  return "~";
}

function getBulletPropertyConfigPath(options = {}) {
  const env =
    options.env ||
    (typeof process !== "undefined" && process.env ? process.env : {});
  const osModule =
    options.osModule === undefined
      ? requireOptionalNodeModule("os")
      : options.osModule;
  const xdgConfigHome =
    typeof env.XDG_CONFIG_HOME === "string" && env.XDG_CONFIG_HOME.trim()
      ? env.XDG_CONFIG_HOME
      : null;
  const configHome =
    xdgConfigHome ||
    joinPathSegments(getBulletPropertyHomeDir(osModule, env), ".config");

  return joinPathSegments(configHome, BULLET_PROPERTY_CONFIG_RELATIVE_PATH);
}

function isBulletPropertyScalar(value) {
  return (
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  );
}

function isValidBulletPropertyName(name) {
  return (
    typeof name === "string" &&
    name.length > 0 &&
    !BULLET_PROPERTY_INVALID_NAME_CHARS_RE.test(name)
  );
}

function normalizeBulletPropertyValues(name, values, options) {
  if (values === "date") {
    return "date";
  }

  if (values === "local_task_id") {
    return "local_task_id";
  }

  if (values === "priority") {
    return "priority";
  }

  if (Array.isArray(values) && values.length > 0) {
    const normalizedValues = [];
    for (const value of values) {
      if (!isBulletPropertyScalar(value)) {
        showBulletPropertyNotice(
          `Bullet property "${name}" values must be "date", "local_task_id", "priority", or a non-empty scalar list`,
          options,
        );
        return null;
      }

      normalizedValues.push(String(value));
    }

    return Object.freeze(normalizedValues);
  }

  showBulletPropertyNotice(
    `Bullet property "${name}" values must be "date", "local_task_id", "priority", or a non-empty scalar list`,
    options,
  );
  return null;
}

function normalizeBulletPriorityLevel(name, level, index, options) {
  const levelPrefix = `Bullet property "${name}" level #${index + 1}`;
  if (!level || typeof level !== "object" || Array.isArray(level)) {
    showBulletPropertyNotice(`${levelPrefix} must be an object`, options);
    return null;
  }

  if (typeof level.label !== "string" || !level.label.trim()) {
    showBulletPropertyNotice(
      `${levelPrefix} must define a non-empty string label`,
      options,
    );
    return null;
  }

  if (!isBulletPropertyScalar(level.value)) {
    showBulletPropertyNotice(
      `${levelPrefix} must define a non-empty scalar value`,
      options,
    );
    return null;
  }

  const label = level.label.trim();
  const rawValue = String(level.value);
  const value = rawValue.trim();
  if (!value) {
    showBulletPropertyNotice(
      `${levelPrefix} must define a non-empty scalar value`,
      options,
    );
    return null;
  }
  if (/[\[\]\n]|::/.test(rawValue)) {
    showBulletPropertyNotice(
      `${levelPrefix} value cannot contain "[", "]", "::", or a newline`,
      options,
    );
    return null;
  }

  if (!Number.isInteger(level.min_days) || level.min_days < 0) {
    showBulletPropertyNotice(
      `${levelPrefix} min_days must be a non-negative integer`,
      options,
    );
    return null;
  }
  if (!Number.isInteger(level.max_days) || level.max_days < 0) {
    showBulletPropertyNotice(
      `${levelPrefix} max_days must be a non-negative integer`,
      options,
    );
    return null;
  }
  if (level.min_days > level.max_days) {
    showBulletPropertyNotice(
      `${levelPrefix} min_days cannot exceed max_days`,
      options,
    );
    return null;
  }

  let levelRolls = null;
  if (
    level.rolls !== undefined &&
    level.rolls !== null
  ) {
    if (!Number.isInteger(level.rolls) || level.rolls < 0) {
      showBulletPropertyNotice(
        `${levelPrefix} rolls must be a non-negative integer`,
        options,
      );
      return null;
    }
    levelRolls = level.rolls;
  }

  return Object.freeze({
    label,
    value,
    minDays: level.min_days,
    maxDays: level.max_days,
    rolls: levelRolls,
  });
}

// Normalize the `decay` block on a priority property. Absent, `true` or `{}` mean
// decay is enabled with the default roll limit; `false` disables decay; otherwise
// `decay.rolls` must be a non-negative integer. Any other key under `decay` is an
// error so a typo such as `roll: 3` is never silently ignored.
function normalizePriorityDecayConfig(name, rawDecay, options) {
  if (rawDecay === undefined || rawDecay === null) {
    return Object.freeze({
      enabled: true,
      rolls: DEFAULT_PRIORITY_DECAY_ROLLS,
    });
  }
  if (rawDecay === true) {
    return Object.freeze({
      enabled: true,
      rolls: DEFAULT_PRIORITY_DECAY_ROLLS,
    });
  }
  if (rawDecay === false) {
    return Object.freeze({ enabled: false, rolls: null });
  }
  if (typeof rawDecay !== "object" || Array.isArray(rawDecay)) {
    showBulletPropertyNotice(
      `Bullet property "${name}" decay must be true, false, or an object with rolls`,
      options,
    );
    return null;
  }
  const knownKeys = new Set(["rolls"]);
  for (const key of Object.keys(rawDecay)) {
    if (!knownKeys.has(key)) {
      showBulletPropertyNotice(
        `Bullet property "${name}" decay has an unknown key "${key}"`,
        options,
      );
      return null;
    }
  }
  if (rawDecay.rolls === undefined || rawDecay.rolls === null) {
    return Object.freeze({
      enabled: true,
      rolls: DEFAULT_PRIORITY_DECAY_ROLLS,
    });
  }
  if (!Number.isInteger(rawDecay.rolls) || rawDecay.rolls < 0) {
    showBulletPropertyNotice(
      `Bullet property "${name}" decay rolls must be a non-negative integer`,
      options,
    );
    return null;
  }
  return Object.freeze({ enabled: true, rolls: rawDecay.rolls });
}

// A level's own `rolls` overrides `decay.rolls` for that level. Null when decay
// is disabled (accepted on levels but ignored).
function getPriorityLevelRollLimit(property, level) {
  const decay = property && property.decay;
  if (!decay || decay.enabled !== true) {
    return null;
  }
  if (level && level.rolls !== undefined && level.rolls !== null) {
    return level.rolls;
  }
  return decay.rolls;
}

function normalizeBulletPriorityProperty(name, entry, options) {
  if (!Array.isArray(entry.levels) || entry.levels.length === 0) {
    showBulletPropertyNotice(
      `Bullet property "${name}" levels must be a non-empty list`,
      options,
    );
    return null;
  }

  const levels = [];
  const seenLabels = new Set();
  const seenValues = new Set();
  for (let index = 0; index < entry.levels.length; index += 1) {
    const level = normalizeBulletPriorityLevel(
      name,
      entry.levels[index],
      index,
      options,
    );
    if (level === null) {
      return null;
    }
    if (seenLabels.has(level.label)) {
      showBulletPropertyNotice(
        `Bullet property "${name}" level #${index + 1} label "${level.label}" is duplicated`,
        options,
      );
      return null;
    }
    if (seenValues.has(level.value)) {
      showBulletPropertyNotice(
        `Bullet property "${name}" level #${index + 1} value "${level.value}" is duplicated`,
        options,
      );
      return null;
    }

    seenLabels.add(level.label);
    seenValues.add(level.value);
    levels.push(level);
  }

  const schedules = entry.schedules === undefined ? "scheduled" : entry.schedules;
  if (typeof schedules !== "string" || !schedules.trim()) {
    showBulletPropertyNotice(
      `Bullet property "${name}" schedules must name another date property`,
      options,
    );
    return null;
  }

  const decay = normalizePriorityDecayConfig(name, entry.decay, options);
  if (decay === null) {
    return null;
  }

  const frozenLevels = Object.freeze(levels);
  return Object.freeze({
    name,
    values: "priority",
    schedules: schedules.trim(),
    levels: frozenLevels,
    levelsByValue: Object.freeze(
      new Map(frozenLevels.map((level) => [level.value, level])),
    ),
    decay,
  });
}

function validateBulletPropertyConfig(config, options = {}) {
  const entries = config && config.properties;
  if (!Array.isArray(entries) || entries.length === 0) {
    showBulletPropertyNotice(
      "Bullet property config must define a non-empty properties list",
      options,
    );
    return null;
  }

  const seenNames = new Set();
  const properties = [];
  for (let index = 0; index < entries.length; index += 1) {
    const entry = entries[index];
    if (!entry || typeof entry.name !== "string") {
      showBulletPropertyNotice(
        `Bullet property entry #${index + 1} must define a string name`,
        options,
      );
      return null;
    }

    const name = entry.name.trim();
    if (!isValidBulletPropertyName(name)) {
      showBulletPropertyNotice(
        `Invalid bullet property name "${name}": names cannot contain whitespace, "::", "[", or "]"`,
        options,
      );
      return null;
    }

    if (seenNames.has(name)) {
      showBulletPropertyNotice(
        `Duplicate bullet property name "${name}" in config`,
        options,
      );
      return null;
    }

    const values = normalizeBulletPropertyValues(name, entry.values, options);
    if (values === null) {
      return null;
    }

    if (
      values !== "priority" &&
      Object.prototype.hasOwnProperty.call(entry, "levels")
    ) {
      showBulletPropertyNotice(
        `Bullet property "${name}" levels are only valid when values is "priority"`,
        options,
      );
      return null;
    }

    if (
      values !== "priority" &&
      Object.prototype.hasOwnProperty.call(entry, "decay")
    ) {
      showBulletPropertyNotice(
        `Bullet property "${name}" decay is only valid when values is "priority"`,
        options,
      );
      return null;
    }

    if (
      values !== "priority" &&
      Object.prototype.hasOwnProperty.call(entry, "rolls")
    ) {
      showBulletPropertyNotice(
        `Bullet property "${name}" rolls is only valid when values is "priority"`,
        options,
      );
      return null;
    }

    seenNames.add(name);
    if (values === "priority") {
      const property = normalizeBulletPriorityProperty(name, entry, options);
      if (property === null) {
        return null;
      }
      properties.push(property);
    } else {
      properties.push(Object.freeze({ name, values }));
    }
  }

  for (const property of properties) {
    if (property.values !== "priority") {
      continue;
    }
    const scheduledProperty = properties.find(
      (candidate) =>
        candidate.name === property.schedules &&
        candidate.name !== property.name &&
        candidate.values === "date",
    );
    if (!scheduledProperty) {
      showBulletPropertyNotice(
        `Bullet property "${property.name}" schedules must name another date property in the same config`,
        options,
      );
      return null;
    }
  }

  return Object.freeze({
    path: options.configPath || null,
    properties: Object.freeze(properties),
  });
}

// ---- src/015-prompt-block-id-naming.js ----
// Prompt block-ID naming contract (plan 202610/task_block_id_prefill.md).
// Pure functions only: no vault reads, no editor writes. Copy-small-helpers:
// an equivalent fragment lives in bob-navigation-hotkeys; both are exercised
// by scripts/prompt-block-id-fixtures.cjs. Do not change the automatic
// successor minting contract (task-status-cycler 086-successor-ids.js).

const PROMPT_BLOCK_ID_STOPWORDS = [
  "a", "an", "and", "as", "at", "be", "by", "for", "from", "in", "into",
  "is", "it", "its", "my", "of", "on", "or", "our", "so", "that", "the",
  "their", "this", "to", "via", "with", "your",
];

const PROMPT_BLOCK_ID_STOPWORD_SET = new Set(PROMPT_BLOCK_ID_STOPWORDS);
const PROMPT_BLOCK_ID_MAX_LENGTH = 32;

function promptBlockIdEscapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function promptBlockIdStripCombining(text) {
  return String(text || "").replace(/[\u0300-\u036f]/g, "");
}

function promptBlockIdNormalizeLatin(text) {
  try {
    return promptBlockIdStripCombining(String(text || "").normalize("NFKD"));
  } catch (error) {
    return String(text || "");
  }
}

// ASCII alphanumeric runs, lowercased, stopwords dropped. Underscores and
// punctuation separate words, never glue them. Latin accents are normalized
// first so `café` contributes `cafe`.
function promptBlockIdWordsIn(text) {
  const normalized = promptBlockIdNormalizeLatin(text);
  const words = [];
  let current = "";
  const flush = () => {
    if (current && !PROMPT_BLOCK_ID_STOPWORD_SET.has(current)) {
      words.push(current);
    }
    current = "";
  };
  for (const ch of normalized) {
    if (
      (ch >= "a" && ch <= "z") ||
      (ch >= "A" && ch <= "Z") ||
      (ch >= "0" && ch <= "9")
    ) {
      current += ch.toLowerCase();
    } else {
      flush();
    }
  }
  flush();
  return words;
}

function promptBlockIdWikilinkPhrase(inner) {
  const text = String(inner || "");
  const aliasIndex = text.indexOf("|");
  if (aliasIndex !== -1) {
    return text.slice(aliasIndex + 1);
  }
  const hashIndex = text.indexOf("#");
  const target = hashIndex === -1 ? text : text.slice(0, hashIndex);
  const slashIndex = target.lastIndexOf("/");
  return slashIndex === -1 ? target : target.slice(slashIndex + 1);
}

function promptBlockIdExtractTaskBody(rawLine) {
  const line = String(rawLine || "");
  const match = line.match(
    /^[ \t]*(?:>[ \t]*)*(?:[-+*]|\d+[.)])[ \t]+\[[^\]\n]\](?:[ \t]+(.*))?$/,
  );
  if (!match) {
    return null;
  }
  return match[1] || "";
}

function promptBlockIdFindProtectedSpans(text) {
  const spans = [];
  const body = String(text || "");
  let match;

  const codeRe = /`([^`\n]*?)`/g;
  while ((match = codeRe.exec(body)) !== null) {
    spans.push({ start: match.index, end: match.index + match[0].length });
  }

  const wikiRe = /\[\[([^\]\n]+?)\]\]/g;
  while ((match = wikiRe.exec(body)) !== null) {
    spans.push({ start: match.index, end: match.index + match[0].length });
  }

  const mdRe = /!?\[[^\]\n]*\]\(([^)\n]+)\)/g;
  while ((match = mdRe.exec(body)) !== null) {
    spans.push({ start: match.index, end: match.index + match[0].length });
  }

  const urlRe = /(?:https?:\/\/|www\.)[^\s)\]]+/g;
  while ((match = urlRe.exec(body)) !== null) {
    spans.push({ start: match.index, end: match.index + match[0].length });
  }

  spans.sort((left, right) => left.start - right.start);
  return spans;
}

function promptBlockIdIndexInSpans(spans, index) {
  for (const span of spans) {
    if (index >= span.start && index < span.end) {
      return true;
    }
  }
  return false;
}

// Clean a task headline for suggestion only; source text is never rewritten
// by this step. Strips the checkbox/list/blockquote prefix (via extract),
// trailing block ID, Dataview inline fields, Tasks emoji date/priority
// metadata, and standalone letter-tags outside code/link labels. Preserves
// semantic numbers such as `#123` and technical text inside code spans.
function promptBlockIdCleanHeadline(rawLine) {
  const body = promptBlockIdExtractTaskBody(rawLine);
  if (body === null) {
    return null;
  }
  let text = body.replace(/[ \t]+\^[A-Za-z0-9-]+[ \t]*$/, "");
  text = text.replace(/[ \t]*\[[^\[\]\n]+::[^\]\n]*\]/g, " ");
  text = text.replace(
    /[ \t]*(?:[\u2600-\u27BF]|\uD83C[\uD000-\uDFFF]|\uD83D[\uD000-\uDFFF]|\uD83E[\uD000-\uDFFF])\s*\d{4}-\d{2}-\d{2}/g,
    " ",
  );
  text = text.replace(/[ \t]+(?:🔁|⏫|🔼|🔽|⏬|📅|🛫|⏳)/g, " ");

  const spans = promptBlockIdFindProtectedSpans(text);
  const tagRe = /(^|[\s([{])#([A-Za-z][A-Za-z0-9/_-]*)/g;
  let result = "";
  let lastIndex = 0;
  let tagMatch;
  while ((tagMatch = tagRe.exec(text)) !== null) {
    const tagStart = tagMatch.index + tagMatch[1].length;
    if (promptBlockIdIndexInSpans(spans, tagStart)) {
      continue;
    }
    result += text.slice(lastIndex, tagStart);
    // Keep the prefix (usually whitespace) so surviving tokens stay
    // separated; collapse later.
    result += tagMatch[1];
    lastIndex = tagStart + 1 + tagMatch[2].length;
  }
  result += text.slice(lastIndex);
  text = result;

  text = text
    .replace(/[ \t]+([,.;:!?])/g, "$1")
    .replace(/[ \t]{2,}/g, " ")
    .trim();
  return text;
}

function promptBlockIdIsBareUrlLike(phrase) {
  const text = String(phrase || "").trim();
  if (!text) {
    return true;
  }
  return /[A-Za-z][A-Za-z0-9+.-]*:\/\//.test(text) || /^www\./i.test(text);
}

// Ordered visible phrases: inline code, straight/curly double-quoted text,
// parenthetical text, wikilinks (alias/basename), Markdown links (label).
// Each Markdown link is one construct so its URL parentheses never become a
// named phrase. Returns visible strings in text order.
function promptBlockIdPhraseSpans(cleaned) {
  const text = String(cleaned || "");
  const chars = Array.from(text);
  const phrases = [];
  let index = 0;

  const offsetsOf = () => {
    const offsets = [];
    let cursor = 0;
    for (const c of chars) {
      offsets.push(cursor);
      cursor += c.length;
    }
    return offsets;
  };

  while (index < chars.length) {
    const ch = chars[index];
    if (ch === "`") {
      const close = chars.indexOf("`", index + 1);
      if (close === -1) {
        index += 1;
        continue;
      }
      phrases.push(chars.slice(index + 1, close).join(""));
      index = close + 1;
      continue;
    }
    if (ch === '"' || ch === "“") {
      let close = -1;
      for (let scan = index + 1; scan < chars.length; scan += 1) {
        if (chars[scan] === '"' || chars[scan] === "”") {
          close = scan;
          break;
        }
      }
      if (close === -1) {
        index += 1;
        continue;
      }
      phrases.push(chars.slice(index + 1, close).join(""));
      index = close + 1;
      continue;
    }
    if (ch === "[" && chars[index + 1] === "[") {
      const offsets = offsetsOf();
      const byteClose = text.indexOf("]]", offsets[index] + 2);
      if (byteClose === -1) {
        index += 2;
        continue;
      }
      let close = chars.length;
      for (let scan = 0; scan < chars.length; scan += 1) {
        if (offsets[scan] === byteClose) {
          close = scan;
          break;
        }
      }
      const inner = chars.slice(index + 2, close).join("");
      phrases.push(promptBlockIdWikilinkPhrase(inner));
      index = close + 2;
      continue;
    }
    if (ch === "[") {
      const offsets = offsetsOf();
      const byteBracket = text.indexOf("]", offsets[index] + 1);
      if (
        byteBracket !== -1 &&
        text[byteBracket + 1] === "("
      ) {
        const byteParen = text.indexOf(")", byteBracket + 2);
        if (byteParen !== -1) {
          let labelEnd = chars.length;
          for (let scan = 0; scan < chars.length; scan += 1) {
            if (offsets[scan] === byteBracket) {
              labelEnd = scan;
              break;
            }
          }
          let parenEnd = chars.length;
          for (let scan = 0; scan < chars.length; scan += 1) {
            if (offsets[scan] === byteParen) {
              parenEnd = scan;
              break;
            }
          }
          // Label excludes a leading `!` image marker (handled by slicing
          // from after `[`, which is exact for `![alt](url)` too).
          phrases.push(chars.slice(index + 1, labelEnd).join(""));
          index = parenEnd + 1;
          continue;
        }
      }
      index += 1;
      continue;
    }
    if (ch === "(") {
      const offsets = offsetsOf();
      const byteClose = text.indexOf(")", offsets[index] + 1);
      if (byteClose === -1) {
        index += 1;
        continue;
      }
      let close = chars.length;
      for (let scan = 0; scan < chars.length; scan += 1) {
        if (offsets[scan] === byteClose) {
          close = scan;
          break;
        }
      }
      phrases.push(chars.slice(index + 1, close).join(""));
      index = close + 1;
      continue;
    }
    index += 1;
  }
  return phrases;
}

// Visible prose projection for the fallback: wikilinks and Markdown links
// become their visible text, code spans lose their backticks, bare URLs are
// removed entirely.
function promptBlockIdProseText(cleaned) {
  let text = String(cleaned || "");
  text = text.replace(
    /!\[([^\]\n]*)\]\(([^)\n]+)\)/g,
    (whole, label) => ` ${label || ""} `,
  );
  text = text.replace(
    /\[([^\]\n]*)\]\(([^)\n]+)\)/g,
    (whole, label) => ` ${label || ""} `,
  );
  text = text.replace(
    /\[\[([^\]\n]+?)\]\]/g,
    (whole, inner) => ` ${promptBlockIdWikilinkPhrase(inner)} `,
  );
  text = text.replace(/`([^`\n]*?)`/g, (whole, inner) => ` ${inner} `);
  text = text.replace(/(?:https?:\/\/|www\.)[^\s)\]]+/g, " ");
  return text;
}

function promptBlockIdTruncateSlug(slug, maxLength) {
  return String(slug || "")
    .slice(0, maxLength)
    .replace(/-+$/g, "");
}

// Join words with `-`, cutting at 32 characters on a `-` boundary where
// possible; a single over-long token is truncated to the limit.
function promptBlockIdJoinTruncated(words, maxLength) {
  const list = Array.isArray(words) ? words : [];
  if (list.length === 0) {
    return null;
  }
  const limit =
    Number.isInteger(maxLength) && maxLength > 0
      ? maxLength
      : PROMPT_BLOCK_ID_MAX_LENGTH;
  const joined = list.join("-");
  if (joined.length <= limit) {
    return joined && /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(joined)
      ? joined
      : null;
  }
  const cut = joined.slice(0, limit).lastIndexOf("-");
  if (cut > 0) {
    return joined.slice(0, cut);
  }
  const truncated = joined.slice(0, limit);
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(truncated) && truncated
    ? truncated
    : joined.slice(0, limit).replace(/[^a-z0-9]+$/g, "") || null;
}

function promptBlockIdCountOccurrences(content, id) {
  const needle = String(id || "");
  if (!needle) {
    return 0;
  }
  const re = new RegExp(
    `(^|[ \\t])\\^${promptBlockIdEscapeRegExp(needle)}(?=$|[ \\t\\r\\n])`,
    "gm",
  );
  let count = 0;
  let match;
  while ((match = re.exec(String(content || ""))) !== null) {
    count += 1;
    // Avoid zero-length infinite loops (pattern always consumes, but guard).
    if (match[0].length === 0) {
      re.lastIndex += 1;
    }
  }
  return count;
}

function promptBlockIdReservedSet(reservedIds) {
  if (reservedIds instanceof Set) {
    return reservedIds;
  }
  return new Set(reservedIds || []);
}

// Pure suggestion over task text, occupied note content, and pending
// reservations. Returns a slug or null for non-task input. Collisions walk
// `stem-2`, `stem-3`, … without a `-9` cutoff, reserving suffix room within
// 32 characters. `excludeId` ignores one occurrence (marker-triggered
// rename); never globally remove duplicates.
function suggestPromptBlockId(rawLine, content, options = {}) {
  const cleaned = promptBlockIdCleanHeadline(rawLine);
  if (cleaned === null) {
    return null;
  }
  const reserved = promptBlockIdReservedSet(options.reservedIds);
  const excludeId =
    typeof options.excludeId === "string" && options.excludeId
      ? options.excludeId
      : null;
  const text = String(content || "");
  const isTaken = (candidate) => {
    if (reserved.has(candidate)) {
      return true;
    }
    let count = promptBlockIdCountOccurrences(text, candidate);
    if (excludeId !== null && candidate === excludeId) {
      count -= 1;
    }
    return count > 0;
  };

  let stem = null;
  const phrases = promptBlockIdPhraseSpans(cleaned);
  for (const phrase of phrases) {
    if (promptBlockIdIsBareUrlLike(phrase)) {
      continue;
    }
    const words = promptBlockIdWordsIn(phrase).slice(0, 4);
    if (words.length === 0) {
      continue;
    }
    const joined = promptBlockIdJoinTruncated(
      words,
      PROMPT_BLOCK_ID_MAX_LENGTH,
    );
    if (joined) {
      stem = joined;
      break;
    }
  }

  if (!stem) {
    const proseWords = promptBlockIdWordsIn(
      promptBlockIdProseText(cleaned),
    ).slice(0, 3);
    if (proseWords.length > 0) {
      stem =
        promptBlockIdJoinTruncated(proseWords, PROMPT_BLOCK_ID_MAX_LENGTH) ||
        "task";
    } else {
      stem = "task";
    }
  }

  let candidate = stem;
  let suffix = 2;
  while (isTaken(candidate)) {
    const suffixText = `-${suffix}`;
    const base =
      promptBlockIdTruncateSlug(
        stem,
        Math.max(1, PROMPT_BLOCK_ID_MAX_LENGTH - suffixText.length),
      ) || "task";
    candidate = `${base}${suffixText}`;
    suffix += 1;
  }
  return candidate;
}
