  const loaded = freezeRelationsCancelLabels(keys, labels);
  if (key != null) {
    relationsCancelLabelsConfigCache = { key, value: loaded };
  } else {
    relationsCancelLabelsConfigCache = { key: null, value: loaded };
  }
