// ---- src/200a-pomodoro-bullet-type-move.js ----
function pomodoroBulletMoveDestinationName(row) {
  if (!row || typeof row !== "object") {
    return "";
  }
  if (row.kind === "existing") {
    return String(getNormalizedPomodoroEntryName(row.entry) || "").trim();
  }
  return String(row.name || "").trim();
}

function pomodoroBulletMovePickerRowKey(row) {
  if (!row || typeof row !== "object") {
    return "";
  }
  if (row.kind === "existing") {
    const entry = row.entry || {};
    return `existing:${entry.entryLine}:${String(entry.name || "")}`;
  }
  return `${String(row.kind || "")}:${String(row.name || "")}`;
}

function pomodoroBulletMoveTypeCandidates(api, destinationName) {
  try {
    const rows = api && typeof api.typeComponentsOf === "function"
      ? api.typeComponentsOf(destinationName)
      : [];
    return (Array.isArray(rows) ? rows : [])
      .filter((row) => row && row.isType === true && row.key && row.name)
      .map((row) => ({ key: String(row.key), name: String(row.name) }));
  } catch (_error) {
    return [];
  }
}

function collectPomodoroBulletMoveTaskLinks(session) {
  const content = String(session && session.sourceContent || "");
  const lines = splitMarkdownContent(content).lines;
  const context = session && session.discovery && session.discovery.context;
  const entry = context && context.entry;
  if (!entry) {
    return [];
  }
  const byIdentity = new Map();
  for (const target of session.discovery.targets || []) {
    const subtree = capturePomodoroBulletSubtree(
      lines,
      target.line,
      entry.childEndLineExclusive,
    );
    for (let line = subtree.startLine; line < subtree.endLineExclusive; line += 1) {
      const rawLine = String(lines[line] || "");
      const link = parseLinkPickerTaskLink(rawLine);
      if (!link) {
        continue;
      }
      const identity = `${link.target}\u0000${link.blockId}`;
      if (!byIdentity.has(identity)) {
        byIdentity.set(identity, Object.freeze({ line, rawLine, link }));
      }
    }
  }
  return [...byIdentity.values()];
}

function pomodoroBulletMoveTaskTypeParts(effective, field) {
  const inherited = effective && effective.inherited
    ? effective.inherited
    : field && field.state === "set"
      ? null
      : effective;
  const theme = effective && effective.theme && typeof effective.theme === "object"
    ? effective.theme
    : null;
  return {
    inherited,
    key: theme && typeof theme.key === "string" ? theme.key : null,
    name: theme && typeof theme.name === "string"
      ? theme.name
      : effective && typeof effective.name === "string"
        ? effective.name
        : null,
  };
}

async function resolvePomodoroBulletMoveTypePreview(plugin, session) {
  const links = collectPomodoroBulletMoveTaskLinks(session);
  const api = getNavigationPomodoroThemesApi(plugin && plugin.app);
  const preview = {
    api,
    candidates: links.length,
    unresolved: 0,
    records: [],
    error: null,
  };
  if (links.length === 0) {
    return preview;
  }
  if (
    !api ||
    typeof api.effectiveTypeFor !== "function" ||
    typeof api.taskThemeOf !== "function" ||
    typeof api.planRetype !== "function"
  ) {
    preview.error = "Task type routing is unavailable";
    return preview;
  }

  const noteContents = new Map();
  const records = [];
  for (const candidate of links) {
    const linkTarget = `${candidate.link.target}#^${candidate.link.blockId}`;
    let file = null;
    try {
      file = plugin.resolveLinkTargetFile(linkTarget, session.sourcePath);
    } catch (_error) {
      file = null;
    }
    if (!file || !plugin.isMarkdownFile(file)) {
      preview.unresolved += 1;
      continue;
    }
    const path = normalizeVaultRelativePath(file.path);
    if (!path) {
      preview.unresolved += 1;
      continue;
    }
    let content;
    if (noteContents.has(path)) {
      content = noteContents.get(path);
    } else if (path === normalizeVaultRelativePath(session.sourcePath)) {
      content = String(session.sourceContent || "");
      noteContents.set(path, content);
    } else {
      try {
        content = await plugin.readLinkPickerNoteContent(path, file);
      } catch (_error) {
        content = null;
      }
      if (typeof content === "string") {
        noteContents.set(path, content);
      }
    }
    if (typeof content !== "string") {
      preview.unresolved += 1;
      continue;
    }
    const resolved = findUniqueLinkPickerTargetLine(
      content,
      candidate.link.blockId,
      { allowClosed: true },
    );
    if (!resolved.valid || !isOpenObsidianTaskLine(resolved.rawLine)) {
      preview.unresolved += 1;
      continue;
    }

    let field;
    let effective;
    try {
      field = api.taskThemeOf(resolved.rawLine);
      effective = api.effectiveTypeFor({
        path,
        line: resolved.line + 1,
        text: content,
      });
    } catch (_error) {
      preview.error = "Task type routing could not read a linked task";
      return preview;
    }
    if (!field || typeof field !== "object") {
      preview.error = "Task type routing could not read a linked task";
      return preview;
    }
    const type = pomodoroBulletMoveTaskTypeParts(effective, field);
    records.push(Object.freeze({
      path,
      file,
      content,
      line: resolved.line,
      rawLine: resolved.rawLine,
      blockId: candidate.link.blockId,
      field,
      effective,
      inherited: type.inherited,
      typeKey: type.key,
      typeName: type.name,
    }));
  }
  preview.records = records;
  return preview;
}

function planPomodoroBulletMoveRetypes(api, records, destinationName, tabPick) {
  if (!api || typeof api.planRetype !== "function") {
    return [];
  }
  return (Array.isArray(records) ? records : []).map((record) => {
    let plan = null;
    try {
      plan = api.planRetype({
        field: record.field,
        effective: record.effective,
        inherited: record.inherited,
        destination: destinationName,
        ...(tabPick ? { tabPick } : {}),
      });
    } catch (_error) {
      plan = null;
    }
    return Object.freeze({ record, plan });
  });
}

function pomodoroBulletMoveRetypeDefaultKey(api, records, destinationName) {
  const plans = planPomodoroBulletMoveRetypes(api, records, destinationName);
  const selected = plans.find((item) => item.plan && item.plan.kind === "set");
  if (selected) {
    return selected.plan.key || null;
  }
  const candidates = pomodoroBulletMoveTypeCandidates(api, destinationName);
  return candidates.length ? candidates[0].key : null;
}

function pomodoroBulletMoveTypeName(effective) {
  const theme = effective && effective.theme && typeof effective.theme === "object"
    ? effective.theme
    : null;
  if (theme && typeof theme.name === "string" && theme.name) {
    return theme.name;
  }
  return effective && typeof effective.name === "string" ? effective.name : "";
}

function mergePomodoroBulletMoveTaskTypes(api, records, destinationName) {
  let name = String(destinationName || "").trim();
  const appended = [];
  for (const record of Array.isArray(records) ? records : []) {
    let outcome = null;
    try {
      outcome = api.planRetype({
        field: record.field,
        effective: record.effective,
        inherited: record.inherited,
        destination: destinationName,
        keepType: true,
      });
    } catch (_error) {
      outcome = null;
    }
    if (!outcome || outcome.kind !== "merge" || !record.typeKey) {
      continue;
    }
    let currentKeys = new Set();
    try {
      currentKeys = new Set(
        (api.typeComponentsOf(name) || []).map((component) => component && component.key).filter(Boolean),
      );
    } catch (_error) {
      currentKeys = new Set();
    }
    if (currentKeys.has(record.typeKey)) {
      continue;
    }
    const typeName = pomodoroBulletMoveTypeName(record.effective);
    if (!typeName) {
      continue;
    }
    name = name ? `${name} + ${typeName}` : typeName;
    appended.push(typeName);
  }
  return Object.freeze({ name, appended: Object.freeze(appended) });
}

function pomodoroBulletMoveSuggestionText(effective) {
  const label = String(effective && effective.label || "").trim();
  const name = pomodoroBulletMoveTypeName(effective);
  if (!label || !name) {
    return "";
  }
  const source = label.replace(/^from\s+/i, "");
  return `${source} suggests ${name}`;
}

function pomodoroBulletMovePickerTabPick(modal, row) {
  const key = pomodoroBulletMovePickerRowKey(row);
  return key && modal.moveTypePicks instanceof Map
    ? modal.moveTypePicks.get(key) || null
    : null;
}

function pomodoroBulletMovePickerCommitOptions(modal, row) {
  return {
    typePreviewState: modal && modal.moveTypePreviewState,
    typeMode: modal && modal.pendingMoveTypeMode === "keepType"
      ? "keepType"
      : "retype",
    tabPick: pomodoroBulletMovePickerTabPick(modal, row),
    typePreview: modal && modal.moveTypePreview,
  };
}

function pomodoroBulletMovePickerConsequence(modal, row) {
  const state = modal && modal.moveTypePreviewState;
  if (state === "loading") {
    return "Checking linked task types…";
  }
  const preview = modal && modal.moveTypePreview;
  if (state === "unavailable" || preview && preview.error) {
    return "Task type preview unavailable · nothing will be moved";
  }
  const candidates = pomodoroBulletMoveTypeCandidates(
    preview && preview.api,
    pomodoroBulletMoveDestinationName(row),
  );
  const destinationName = pomodoroBulletMoveDestinationName(row) || "unnamed";
  const records = preview && Array.isArray(preview.records) ? preview.records : [];
  if (!preview || !preview.candidates) {
    return "no live link · ledger unchanged";
  }
  if (records.length === 0) {
    const unresolved = preview.unresolved > 0
      ? ` · ${preview.unresolved} links not retyped`
      : "";
    return `${destinationName} · no open task types change${unresolved}`;
  }

  const selectedPick = pomodoroBulletMovePickerTabPick(modal, row);
  const plans = planPomodoroBulletMoveRetypes(
    preview.api,
    records,
    destinationName,
    selectedPick,
  );
  const changes = plans.filter((item) =>
    item.plan && (item.plan.kind === "set" || item.plan.kind === "clear"),
  );
  let targetLabel = destinationName;
  const setNames = [...new Set(changes
    .filter((item) => item.plan.kind === "set")
    .map((item) => item.plan.name)
    .filter(Boolean))];
  const clearCount = changes.filter((item) => item.plan.kind === "clear").length;
  if (setNames.length === 1 && clearCount === 0) {
    targetLabel = setNames[0];
  } else if (setNames.length === 0 && clearCount > 0) {
    const inheritedName = changes.find((item) => item.plan.kind === "clear")
      ?.record.inherited;
    targetLabel = pomodoroBulletMoveTypeName(inheritedName) || destinationName;
  }
  let consequence;
  if (changes.length === 0) {
    const kept = [...new Set(records.map((record) => record.typeName).filter(Boolean))];
    consequence = kept.length === 1
      ? `→ ${destinationName} · keeps ${kept[0]}`
      : `→ ${destinationName} · keeps task types`;
  } else if (clearCount > 0 && setNames.length === 0 && changes.length === 1) {
    const inherited = changes[0].record.inherited;
    const label = String(inherited && inherited.label || "").trim();
    consequence = `→ ${targetLabel} · type cleared${label ? ` · ${label}` : ""}`;
  } else if (setNames.length === 1 && clearCount === 0) {
    const taskCount = changes.length === 1 ? "task" : `${changes.length} tasks`;
    consequence = `→ ${targetLabel} · ${taskCount} become${changes.length === 1 ? "s" : ""} ${targetLabel}`;
    if (changes.length === 1) {
      const suggestion = pomodoroBulletMoveSuggestionText(changes[0].record.effective);
      if (suggestion) {
        consequence += ` · ${suggestion}`;
      }
    }
  } else {
    consequence = `→ ${destinationName} · ${changes.length} task types change`;
  }

  const merged = mergePomodoroBulletMoveTaskTypes(
    preview.api,
    records,
    destinationName,
  );
  if (merged.name && merged.name !== destinationName) {
    const names = [...new Set(records.map((record) => record.typeName).filter(Boolean))];
    if (records.length === 1 && names.length === 1) {
      consequence += ` · ⌥↵ keep ${names[0]} (${merged.name})`;
    } else {
      consequence += ` · ⌥↵ keep types (${merged.name})`;
    }
  }
  if (candidates.length > 1) {
    const currentKey = selectedPick || pomodoroBulletMoveRetypeDefaultKey(
      preview.api,
      records,
      destinationName,
    );
    const currentIndex = Math.max(0, candidates.findIndex((item) => item.key === currentKey));
    const next = candidates[(currentIndex + 1) % candidates.length];
    if (next) {
      consequence += ` · ⇥ ${next.name}`;
    }
  }
  if (preview.unresolved > 0) {
    consequence += ` · ${preview.unresolved} links not retyped`;
  }
  return consequence;
}

function pomodoroEntryRenameTypeConsequence(modal, row) {
  const isRename = row && (row.kind === "rename" ||
    (row.kind === "recent" && row.operation === "rename"));
  if (!isRename) {
    return null;
  }
  const state = modal && modal.renameTypePreviewState;
  if (state === "loading") {
    return "Checking linked task types…";
  }
  const preview = modal && modal.renameTypePreview;
  if (state === "unavailable" || preview && preview.error) {
    return "Task type preview unavailable · nothing will be renamed";
  }
  if (!preview || !preview.candidates) {
    return "No linked tasks · task types unchanged";
  }
  const plans = pomodoroBulletMoveTypePlanRows(
    preview.api,
    preview,
    String(row.name || "").trim(),
    {},
  );
  if (plans.some((item) => !item.plan)) {
    return "Task type preview unavailable · nothing will be renamed";
  }
  const changes = new Map();
  let inheritedCount = 0;
  for (const item of plans) {
    if (item.plan.kind === "set") {
      const name = String(item.plan.name || "type");
      changes.set(name, (changes.get(name) || 0) + 1);
    } else if (item.plan.kind === "clear") {
      inheritedCount += 1;
    }
  }
  const countText = (count, singular, plural) => `${count} ${count === 1 ? singular : plural}`;
  const pieces = [...changes.entries()].map(([name, count]) =>
    `${countText(count, "task", "tasks")} ${count === 1 ? "becomes" : "become"} ${name}`,
  );
  if (inheritedCount > 0) {
    pieces.push(`${countText(inheritedCount, "task", "tasks")} ${inheritedCount === 1 ? "uses" : "use"} inherited types`);
  }
  if (pieces.length === 0) {
    const container = plans.some((item) => item.plan.kind === "container");
    const unresolved = Number(preview.unresolved) || 0;
    const reason = container
      ? "Container or label destination · no task types change"
      : "All linked tasks already agree · no task types change";
    return unresolved > 0 ? `${reason} · ${unresolved} links not checked` : reason;
  }
  const unresolved = Number(preview.unresolved) || 0;
  const suffix = unresolved > 0 ? ` · ${unresolved} links not checked` : "";
  return `${pieces.join(" · ")}${suffix}`;
}

function cyclePomodoroBulletMoveType(modal, row, backwards = false) {
  const preview = modal && modal.moveTypePreview;
  if (!preview || preview.error || !preview.api) {
    return false;
  }
  const destinationName = pomodoroBulletMoveDestinationName(row);
  const candidates = pomodoroBulletMoveTypeCandidates(preview.api, destinationName);
  if (candidates.length < 2) {
    return false;
  }
  const rowKey = pomodoroBulletMovePickerRowKey(row);
  const selected = pomodoroBulletMovePickerTabPick(modal, row);
  const currentKey = selected || pomodoroBulletMoveRetypeDefaultKey(
    preview.api,
    preview.records,
    destinationName,
  );
  const currentIndex = Math.max(0, candidates.findIndex((item) => item.key === currentKey));
  const nextIndex = (currentIndex + (backwards ? -1 : 1) + candidates.length) % candidates.length;
  modal.moveTypePicks.set(rowKey, candidates[nextIndex].key);
  modal.renderResults();
  return true;
}

function installPomodoroEntryMoveTypePreview() {
  const prototype = PomodoroEntryMovePickerModal.prototype;
  const originalOnOpen = prototype.onOpen;
  const originalRenderResults = prototype.renderResults;
  const originalRenderFooter = prototype.renderFooter;

  prototype.onOpen = function () {
    const linkedTaskCount = collectPomodoroBulletMoveTaskLinks(this.session).length;
    this.renameTypePreviewState = linkedTaskCount > 0 ? "loading" : "ready";
    this.renameTypePreview = linkedTaskCount > 0
      ? null
      : { api: this.themesApi, candidates: 0, unresolved: 0, records: [], error: null };
    originalOnOpen.call(this);
    if (linkedTaskCount === 0) {
      return;
    }
    void resolvePomodoroBulletMoveTypePreview(this.plugin, this.session)
      .then((preview) => {
        if (!this.pickerOpen) return;
        this.renameTypePreview = preview;
        this.renameTypePreviewState = preview.error ? "unavailable" : "ready";
        this.renderResults();
      })
      .catch(() => {
        if (!this.pickerOpen) return;
        this.renameTypePreview = { candidates: 0, unresolved: 0, records: [], error: "Task type preview failed" };
        this.renameTypePreviewState = "unavailable";
        this.renderResults();
      });
  };

  prototype.renderFooter = function () {
    originalRenderFooter.call(this);
    if (!this.footerEl) return;
    const row = (this.visibleItems || [])[this.selectedIndex];
    const consequence = pomodoroEntryRenameTypeConsequence(this, row);
    if (consequence) {
      this.footerEl.createDiv({ cls: "bob-cnp-consequence-strip-text", text: consequence });
    }
  };

  prototype.renderResults = function () {
    originalRenderResults.call(this);
    this.renderFooter();
  };
}

function installPomodoroBulletMoveTypePicker() {
  const prototype = PomodoroBulletMovePickerModal.prototype;
  const originalOnOpen = prototype.onOpen;
  const originalRenderResults = prototype.renderResults;
  const originalRenderFooter = prototype.renderFooter;
  const originalHandleKeydown = prototype.handleKeydown;

  prototype.onOpen = function () {
    const candidates = collectPomodoroBulletMoveTaskLinks(this.session);
    const api = getNavigationPomodoroThemesApi(this.app);
    this.moveTypePreviewState = candidates.length === 0 ? "ready" : "loading";
    this.moveTypePreview = candidates.length === 0
      ? { api, candidates: 0, unresolved: 0, records: [], error: null }
      : null;
    this.moveTypePicks = new Map();
    this.pendingMoveTypeMode = "retype";
    originalOnOpen.call(this);
    if (candidates.length === 0) {
      return;
    }
    void resolvePomodoroBulletMoveTypePreview(this.plugin, this.session)
      .then((preview) => {
        if (!this.pickerOpen) {
          return;
        }
        this.moveTypePreview = preview;
        this.moveTypePreviewState = preview.error ? "unavailable" : "ready";
        this.renderResults();
      })
      .catch(() => {
        if (!this.pickerOpen) {
          return;
        }
        this.moveTypePreview = {
          candidates: 0,
          unresolved: 0,
          records: [],
          error: "Task type preview failed",
        };
        this.moveTypePreviewState = "unavailable";
        this.renderResults();
      });
  };

  prototype.renderFooter = function () {
    originalRenderFooter.call(this);
    if (this.footerEl) {
      this.footerEl.createDiv({
        cls: "bob-cnp-consequence-strip-text",
        text: pomodoroBulletMovePickerConsequence(
          this,
          (this.visibleItems || [])[this.selectedIndex],
        ),
      });
    }
  };

  prototype.renderResults = function () {
    originalRenderResults.call(this);
    this.renderFooter();
  };

  prototype.handleKeydown = function (event) {
    if (
      event &&
      event.key === "Enter" &&
      event.altKey === true &&
      event.ctrlKey !== true &&
      event.metaKey !== true
    ) {
      event.preventDefault();
      event.stopPropagation();
      if (!this.opening) {
        this.pendingMoveTypeMode = "keepType";
        this.openSelectedItem();
      }
      return;
    }
    if (
      event &&
      event.key === "Tab" &&
      event.altKey !== true &&
      event.ctrlKey !== true &&
      event.metaKey !== true &&
      event.isComposing !== true
    ) {
      const row = (this.visibleItems || [])[this.selectedIndex];
      if (cyclePomodoroBulletMoveType(this, row, event.shiftKey === true)) {
        event.preventDefault();
        event.stopPropagation();
        return;
      }
    }
    originalHandleKeydown.call(this, event);
  };
}

installPomodoroEntryMoveTypePreview();
installPomodoroBulletMoveTypePicker();
// ---- src/201-pomodoro-theme-picker-rows.js ----
function addPickerRowClasses(rowEl, classes) {
  const list = Array.isArray(classes) ? classes : [classes];
  if (rowEl && rowEl.classList && typeof rowEl.classList.add === "function") {
    rowEl.classList.add(...list.filter(Boolean));
    return;
  }
  if (rowEl && typeof rowEl.addClass === "function") {
    list.filter(Boolean).forEach((cls) => rowEl.addClass(cls));
  }
}

function renderPomodoroBulletMovePickerRow(row, rowEl, query, themesApi) {
  const kind = row && row.kind ? row.kind : "invalid";
  addPickerRowClasses(rowEl, [
    "bob-cnp-pomodoro-row",
    `is-${kind}`,
    row && row.hidden ? "is-hidden-theme" : "",
  ]);

  const rowIcon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
  const iconName =
    kind === "new" || (kind === "recent" && row.operation === "new")
      ? "plus"
      : kind === "rename" || (kind === "recent" && row.operation === "rename")
        ? "pencil"
        : kind === "split"
          ? "split"
          : kind === "invalid"
            ? "circle-alert"
            : "timer";
  applyIcon(rowIcon, iconName);

  const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
  const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
  if (kind === "recent" || kind === "new" || kind === "rename") {
    const rename = kind === "rename" || (kind === "recent" && row.operation === "rename");
      titleEl.appendText(rename ? "Rename Pomodoro to " : "New Pomodoro ");
    renderNavigationPomodoroThemeSwatches(titleEl, themesApi, row.name);
    appendHighlighted(titleEl, row.name, query);
  } else {
    if (kind === "existing") {
      renderNavigationPomodoroThemeSwatches(
        titleEl,
        themesApi,
        row.entry && row.entry.name,
      );
    }
    appendHighlighted(titleEl, kind === "invalid" ? row.statusText : row.title, query);
  }
  const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
  appendHighlighted(
    pathEl,
    kind === "invalid" ? "Type a valid Pomodoro name" : row.meta,
    query,
  );

  const badgesEl = rowEl.createDiv({ cls: "bob-cnp-row-badges" });
  if (kind === "recent") {
    badgesEl.createDiv({
      cls: `bob-cnp-row-status is-recent-theme${row.hidden ? " is-hidden-theme" : ""}`,
      text: row.hidden ? "Hidden" : "Recent",
      attr: {
        title: row.hidden ? "Type hidden from Recent; Ctrl+D to unhide" : "Recent task type",
        "aria-label": row.hidden ? "Hidden type" : "Recent type",
      },
    });
    return;
  }
  if (kind === "new" || kind === "rename" || kind === "split") {
    const statusEl = badgesEl.createDiv({
      cls: "bob-cnp-row-status is-create",
    });
    appendHighlighted(statusEl, row.badge || "New", query);
    if (row.unconfigured) {
      badgesEl.createDiv({
        cls: "bob-cnp-row-status is-warning",
      text: "Not a configured type",
        attr: {
          title: "This name isn't in your configured types",
          "aria-label": "Not a configured type",
        },
      });
    }
    for (const similar of row.similarTo || []) {
      badgesEl.createDiv({
        cls: "bob-cnp-row-status is-similar-theme",
        text: `like ${similar}`,
        attr: { title: `Similar to ${similar}` },
      });
    }
    if (row.hiddenThemes && row.hiddenThemes.length > 0) {
      badgesEl.createDiv({
        cls: "bob-cnp-row-status is-hidden-theme",
        text: "Hidden · ^D unhide",
      });
    }
    return;
  }
  if (kind === "invalid") {
    const statusEl = badgesEl.createDiv({
      cls: "bob-cnp-row-status is-unavailable",
    });
    appendHighlighted(statusEl, "Not selectable", query);
    return;
  }
  if (!row.statusLabel) {
    return;
  }

  const statusClass =
    row.statusLabel === "Unscheduled" ? " is-status-unscheduled" : "";
  const statusEl = badgesEl.createDiv({
    cls: `bob-cnp-row-status${statusClass}`,
    attr: {
      "aria-label": row.statusLabel,
      title: row.statusLabel,
    },
  });
  appendHighlighted(
    statusEl,
    [row.statusEmoji, row.statusLabel].filter(Boolean).join(" "),
    query,
  );
}
// ---- src/202-pomodoro-themes-manager.js ----
// Bob Pomodoro themes manager: browse, hide, pin, inspect, and rename themes.
// Ledger Tools `api.themes` owns the catalog, hues, ranking, and writes; this
// file only composes the manager picker, its action/color/occurrences/rename
// modals, and the pure row models the tests cover. Mobile stays a Notice:
// history and writes need the desktop app.

const POMODORO_THEMES_MANAGER_VIEWS = ["active", "hidden", "duplicates", "all"];

const POMODORO_THEMES_MANAGER_VIEW_LABELS = {
  active: "Active",
  hidden: "Hidden",
  duplicates: "Possible duplicates",
  all: "All",
};

const POMODORO_THEMES_MANAGER_HUES = [
  "blue",
  "orange",
  "aqua",
  "yellow",
  "magenta",
  "green",
  "violet",
  "red",
];

const POMODORO_THEMES_MANAGER_COLOR_KEYS = ["1", "2", "3", "4", "5", "6", "7", "8", "a"];

const POMODORO_THEMES_MANAGER_HINTS = [
  { keys: ["Tab"], label: "Switch view" },
  { keys: ["↵"], label: "Rename · color · hide · occurrences" },
  { keys: ["^D"], label: "Hide / undo" },
  { keys: ["esc"], label: "Dismiss" },
];

function normalizePomodoroThemeManagerKey(value) {
  return String(value || "").replace(/\s+/g, " ").trim().toLowerCase();
}

// Relative day label for a `YYYY-MM-DD` date against today's `YYYY-MM-DD`.
function formatPomodoroThemeManagerRelative(isoDate, todayIso) {
  const date = String(isoDate || "");
  const today = String(todayIso || "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return "unknown";
  }
  if (date === today) {
    return "today";
  }
  const dayMs = 24 * 60 * 60 * 1000;
  const parsed = Date.parse(`${date}T00:00:00Z`);
  const parsedToday = Date.parse(`${today}T00:00:00Z`);
  if (Number.isFinite(parsed) && Number.isFinite(parsedToday)) {
    const diff = Math.round((parsedToday - parsed) / dayMs);
    if (diff === 1) {
      return "yesterday";
    }
    if (diff > 1 && diff <= 6) {
      return `${diff} days ago`;
    }
  }
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const parts = date.split("-");
  const month = months[Number(parts[1]) - 1] || parts[1];
  if (date.slice(0, 4) === today.slice(0, 4)) {
    return `${month} ${Number(parts[2])}`;
  }
  return `${month} ${Number(parts[2])} ${parts[0]}`;
}

function pomodoroThemesManagerStripPunctuation(key) {
  return String(key || "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

// Levenshtein distance capped at 2: anything above 1 is just "far".
function pomodoroThemesManagerLevenshteinCapped(left, right) {
  const a = String(left || "");
  const b = String(right || "");
  if (Math.abs(a.length - b.length) > 1) {
    return 2;
  }
  let prev = [];
  for (let j = 0; j <= b.length; j += 1) {
    prev.push(j);
  }
  for (let i = 1; i <= a.length; i += 1) {
    const curr = [i];
    let rowMin = i;
    for (let j = 1; j <= b.length; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      const value = Math.min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost);
      curr.push(value);
      if (value < rowMin) {
        rowMin = value;
      }
    }
    if (rowMin > 1) {
      return 2;
    }
    prev = curr;
  }
  return prev[b.length] > 1 ? 2 : prev[b.length];
}

// Possible-duplicate pairs across the catalog, using the PT7 near-duplicate
// rule: equal modulo space, hyphen, and punctuation, plural/singular (`s`,
// `es`), or Levenshtein distance 1 when both keys have at least 5 characters.
function pomodoroThemesManagerDuplicatePairs(themes) {
  const list = (Array.isArray(themes) ? themes : []).filter(
    (theme) => theme && typeof theme.key === "string" && theme.key,
  );
  const pairs = [];
  for (let i = 0; i < list.length; i += 1) {
    for (let j = i + 1; j < list.length; j += 1) {
      const left = list[i].key;
      const right = list[j].key;
      if (!left || !right || left === right) {
        continue;
      }
      let qualifies = false;
      const strippedLeft = pomodoroThemesManagerStripPunctuation(left);
      const strippedRight = pomodoroThemesManagerStripPunctuation(right);
      if (strippedLeft && strippedLeft === strippedRight) {
        qualifies = true;
      }
      if (
        !qualifies &&
        (right === `${left}s` || right === `${left}es` || left === `${right}s` || left === `${right}es`)
      ) {
        qualifies = true;
      }
      if (
        !qualifies &&
        left.length >= 5 &&
        right.length >= 5 &&
        pomodoroThemesManagerLevenshteinCapped(left, right) <= 1
      ) {
        qualifies = true;
      }
      if (qualifies) {
        const first = list[i].name < list[j].name ? list[i] : list[j];
        const second = first === list[i] ? list[j] : list[i];
        pairs.push({ a: first, b: second });
      }
    }
  }
  pairs.sort((left, right) => {
    const leftKey = `${left.a.key}\0${left.b.key}`;
    const rightKey = `${right.a.key}\0${right.b.key}`;
    return leftKey < rightKey ? -1 : leftKey > rightKey ? 1 : 0;
  });
  return pairs;
}

// Build the manager rows for one view. Hint rows (collision hints) stay on
// top; theme rows carry badges; renamed-reappeared names are flagged.
function buildPomodoroThemesManagerRows(report, view) {
  const current = POMODORO_THEMES_MANAGER_VIEWS.includes(view) ? view : "active";
  const themes = report && Array.isArray(report.themes) ? report.themes : [];
  const hints = report && Array.isArray(report.hints) ? report.hints : [];
  const reappeared = new Set(report && Array.isArray(report.renamed_reappeared) ? report.renamed_reappeared : []);
  const rows = [];
  if ((current === "active" || current === "all") && hints.length > 0) {
    for (const hint of hints) {
      if (!hint || hint.code !== "theme_hue_collision") {
        continue;
      }
      const names = Array.isArray(hint.themes) ? hint.themes : [];
      const suggestion = hint.suggest && hint.suggest.name ? ` → ${hint.suggest.name} ${hint.suggest.hue || ""}`.trimEnd() : "";
      rows.push({
        kind: "hint",
        key: `hint-${names.join("+")}`,
        title: `${names.join(" and ")} share ${hint.hue || "a hue"}${suggestion}`,
        hint,
      });
    }
  }
  const duplicateKeys = new Set();
  if (current === "duplicates") {
    for (const pair of pomodoroThemesManagerDuplicatePairs(themes)) {
      duplicateKeys.add(pair.a.key);
      duplicateKeys.add(pair.b.key);
    }
  }
  for (const theme of themes) {
    if (!theme || typeof theme.key !== "string") {
      continue;
    }
    const hidden = theme.hidden === true;
    if (current === "active" && hidden) {
      continue;
    }
    if (current === "hidden" && !hidden) {
      continue;
    }
    if (current === "duplicates" && !duplicateKeys.has(theme.key)) {
      continue;
    }
    const badges = [];
    if (theme.today === "open" || theme.today === "closed") {
      badges.push("today");
    }
    if (hidden) {
      badges.push("hidden");
    }
    if (theme.pinned === true) {
      badges.push("pinned");
    }
    if (theme.exempt === true) {
      badges.push("exempt");
    }
    if (theme.configured === false) {
      badges.push("not configured");
    }
    if (reappeared.has(theme.key) || reappeared.has(theme.name)) {
      badges.push("reappeared");
    }
    rows.push({ kind: "theme", key: `theme-${theme.key}`, theme, badges });
  }
  return rows;
}

function filterPomodoroThemesManagerRows(rows, query) {
  const trimmed = String(query || "").trim().toLowerCase().replace(/\s+/g, " ");
  if (!trimmed) {
    return rows;
  }
  return (Array.isArray(rows) ? rows : []).filter((row) => {
    if (!row) {
      return false;
    }
    if (row.kind === "hint") {
      return String(row.title || "").toLowerCase().includes(trimmed);
    }
    if (row.kind === "theme" && row.theme) {
      return (
        String(row.theme.name || "").toLowerCase().includes(trimmed) ||
        String(row.theme.key || "").includes(trimmed)
      );
    }
    return true;
  });
}

// Validate a rename target: a valid single theme (a `+` makes invalid_name).
function pomodoroThemesManagerRenameInputError(raw) {
  const validated = normalizePomodoroName(raw);
  if (!validated.valid) {
    return validated.error;
  }
  if (validated.name.includes("+")) {
    return "Rename to a single type without +";
  }
  return null;
}

// Human rename preview from a `bob themes rename --dry-run -f json` report.
function formatPomodoroThemeManagerRenamePreview(dryRun) {
  const empty = { title: "No rename preview", lines: [], stateNote: "", colorNote: "", entries: 0, files: 0 };
  if (!dryRun || typeof dryRun !== "object") {
    return empty;
  }
  const report = dryRun.report && typeof dryRun.report === "object" ? dryRun.report : dryRun;
  if (!report || typeof report !== "object") {
    return empty;
  }
  const from = report.from && report.from.name ? report.from.name : "";
  const to = report.to && report.to.name ? report.to.name : "";
  const files = Array.isArray(report.files) ? report.files : [];
  const entries = Number.isFinite(Number(report.entries)) ? Number(report.entries) : 0;
  const lines = files.map((file) => {
    const tails = Array.isArray(file.tails) ? file.tails : [];
    const tailText = tails
      .map((tail) => `${tail.before || ""} → ${tail.after || ""}`)
      .join("; ");
    return `${file.path || ""} · ${file.entries || 0} ${Number(file.entries) === 1 ? "entry" : "entries"}${tailText ? ` · ${tailText}` : ""}`;
  });
  const stateNote = report.state && report.state.note ? String(report.state.note) : "";
  const colorNote = report.color && report.color.note ? String(report.color.note) : "";
  return {
    title: `${from} → ${to} · ${entries} ${entries === 1 ? "entry" : "entries"} in ${files.length} ${files.length === 1 ? "note" : "notes"}`,
    lines,
    stateNote,
    colorNote,
    entries,
    files: files.length,
  };
}

// Scan one note's text for Pomodoro entries whose ` — NAME` tail contains the
// theme key. Returns `{ path, line, tail }` rows with 0-based line numbers.
function collectPomodoroThemeOccurrencesInText(path, content, key) {
  const wanted = normalizePomodoroThemeManagerKey(key);
  if (!wanted) {
    return [];
  }
  const rows = [];
  const lines = String(content || "").split("\n");
  const isFence = (text) => /^```/.test(String(text || "").trimStart().slice(0, 3)) || /^\s*```/.test(text);
  let fenced = false;
  lines.forEach((rawLine, index) => {
    const text = String(rawLine || "");
    if (/^\s*```/.test(text)) {
      fenced = !fenced;
      return;
    }
    if (fenced || isFence(text)) {
      return;
    }
    if (!/^\s*-\s*\[[ xX?\/-]\]/.test(text)) {
      return;
    }
    const separator = text.indexOf(" — ");
    if (separator === -1) {
      return;
    }
    // Task lines (`#task`) are not Pomodoro entries, even with a checkbox.
    if (text.slice(0, separator).includes("#task")) {
      return;
    }
    const tail = text.slice(separator + 3).trim();
    if (!tail) {
      return;
    }
    const components = tail.split("+").map((part) => part.trim()).filter(Boolean);
    if (components.some((part) => normalizePomodoroThemeManagerKey(part) === wanted)) {
      rows.push({ path, line: index, tail });
    }
  });
  return rows;
}

// Daily-note scope for occurrences and rename-adjacent scans: canonical
// `YYYY/YYYYMMDD.md` notes plus `_templates/daily.md`.
function isPomodoroThemeManagerDailyPath(path) {
  const value = String(path || "");
  if (value === "_templates/daily.md") {
    return true;
  }
  return /^\d{4}\/\d{8}\.md$/.test(value);
}

function renderPomodoroThemesManagerRow(row, rowEl, query, themesApi) {
  if (!row || !rowEl) {
    return;
  }
  if (row.kind === "hint") {
    addPickerRowClasses(rowEl, ["bob-cnp-pomodoro-row", "is-hint"]);
    const iconEl = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(iconEl, "lightbulb");
    const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
    appendHighlighted(titleEl, row.title, query);
    const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
    pathEl.setText("Suggestion — Tab past it to browse types");
    return;
  }
  if (row.kind !== "theme" || !row.theme) {
    return;
  }
  const theme = row.theme;
  addPickerRowClasses(rowEl, [
    "bob-cnp-pomodoro-row",
    "is-theme",
    theme.hidden === true ? "is-hidden-theme" : "",
    theme.configured === false ? "is-unconfigured-theme" : "",
  ]);
  const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
  const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
  renderNavigationPomodoroThemeSwatches(titleEl, themesApi, theme.name);
  appendHighlighted(titleEl, theme.name, query);
  const days = Math.max(0, Number(theme.days_used) || 0);
  const lastUsed = theme.last_used ? formatPomodoroThemeManagerRelative(theme.last_used, "") : "unknown";
  const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
  const entries = Math.max(0, Number(theme.entries) || 0);
  appendHighlighted(
    pathEl,
    `${lastUsed} · ${days} ${days === 1 ? "day" : "days"} · ${entries} ${entries === 1 ? "entry" : "entries"}`,
    query,
  );
  const badgesEl = rowEl.createDiv({ cls: "bob-cnp-row-badges" });
  for (const badge of row.badges || []) {
    const cls =
      badge === "hidden"
        ? "bob-cnp-row-status is-hidden-theme"
        : badge === "reappeared"
          ? "bob-cnp-row-status is-similar-theme"
          : badge === "not configured"
            ? "bob-cnp-row-status is-warning"
          : "bob-cnp-row-status is-recent-theme";
    const label =
      badge === "reappeared"
        ? "reappeared — rename again?"
        : badge.slice(0, 1).toUpperCase() + badge.slice(1);
    badgesEl.createDiv({
      cls,
      text: label,
      attr: { title: label, "aria-label": `${theme.name}: ${label}` },
    });
  }
  if (theme.hue) {
    const source = theme.hue_source === "config"
      ? " · config"
      : theme.pinned === true
        ? " · pinned"
        : "";
    badgesEl.createDiv({
      cls: "bob-cnp-row-status",
      text: `${theme.hue}${source}`,
      attr: {
        title: theme.hue_source === "config"
          ? "Color set in ~/.config/bob/config.yml"
          : `Hue ${theme.hue}${theme.pinned === true ? " (pinned)" : ""}`,
      },
    });
  }
}

class PomodoroThemesManagerModal extends FilteredPickerModal {
  constructor(app, plugin) {
    const themesApi = getNavigationPomodoroThemesApi(app);
    super(app, {
      items: [],
      title: "Types",
      headerIcon: "timer",
      inputLabel: "Filter types",
      placeholder: "Filter types — Tab switches view",
      resultsLabel: "Types",
      emptyText: "No types match",
      footerHints: POMODORO_THEMES_MANAGER_HINTS,
      getSubtitle: () => this.managerSubtitle(),
      filterItem: (row, query) => filterPomodoroThemesManagerRows([row], query).length > 0,
      renderItem: (row, rowEl, query) => renderPomodoroThemesManagerRow(row, rowEl, query, this.themesApi),
      closeBeforeOpenItem: true,
      openItem: (row) => this.openThemeActions(row),
    });
    this.plugin = plugin;
    this.themesApi = themesApi;
    this.managerView = "active";
    this.managerReport = null;
    this.managerError = null;
    this.themeWriteInFlight = false;
  }

  managerSubtitle() {
    const label = POMODORO_THEMES_MANAGER_VIEW_LABELS[this.managerView] || "Active";
    const counts = this.managerReport && this.managerReport.counts ? this.managerReport.counts : null;
    const known = counts && counts.known !== undefined ? ` · ${counts.known} known` : "";
    const suffix = this.managerError ? ` · ${this.managerError}` : "";
    return `${label} view · Tab switches${known}${suffix}`;
  }

  managerAvailable() {
    return navigationPomodoroThemeAvailable(this.themesApi);
  }

  onOpen() {
    super.onOpen();
    if (!this.managerAvailable()) {
      new Notice("Task types need the desktop app.");
      this.close();
      return;
    }
    startNavigationPomodoroThemePicker(this);
    void this.refreshManagerReport("open");
  }

  async refreshManagerReport(reason) {
    void reason;
    if (!this.themesApi || typeof this.themesApi.fetch !== "function") {
      return;
    }
    try {
      const result = await this.themesApi.fetch();
      if (!this.pickerOpen) {
        return;
      }
      if (result && result.report) {
        this.managerReport = result.report;
        this.managerError = null;
      } else if (result && result.error && result.error.message) {
        this.managerError = result.error.message;
      }
      this.rebuildManagerItems();
    } catch (error) {
      this.managerError = "Could not load types";
      this.rebuildManagerItems();
    }
  }

  rebuildManagerItems() {
    this.items = buildPomodoroThemesManagerRows(this.managerReport, this.managerView);
    this.selectedIndex = 0;
    this.renderResults();
  }

  getFilteredItems() {
    const query = this.getRawQuery();
    return filterPomodoroThemesManagerRows(this.items, query);
  }

  cycleManagerView() {
    const index = POMODORO_THEMES_MANAGER_VIEWS.indexOf(this.managerView);
    this.managerView = POMODORO_THEMES_MANAGER_VIEWS[(index + 1) % POMODORO_THEMES_MANAGER_VIEWS.length];
    this.selectedIndex = 0;
    this.rebuildManagerItems();
  }

  selectedThemeRow() {
    const row = this.visibleItems && this.visibleItems[this.selectedIndex];
    return row && row.kind === "theme" ? row : null;
  }

  handleKeydown(event) {
    if (event.key === "Tab") {
      event.preventDefault();
      event.stopPropagation();
      this.cycleManagerView();
      return;
    }
    if (isCtrlKey(event, "d")) {
      event.preventDefault();
      event.stopPropagation();
      void this.toggleSelectedThemeVisibility();
      return;
    }
    super.handleKeydown(event);
  }

  async toggleSelectedThemeVisibility() {
    await this.toggleThemeRowVisibility(this.selectedThemeRow());
  }

  async toggleThemeRowVisibility(row) {
    if (!row || row.kind !== "theme" || !this.themesApi || this.themeWriteInFlight) {
      return;
    }
    const method = row.theme.hidden === true ? "unhide" : "hide";
    if (typeof this.themesApi[method] !== "function") {
      new Notice("Update bob to hide types");
      return;
    }
    this.themeWriteInFlight = true;
    try {
      const result = await this.themesApi[method](row.theme.name);
      if (!result || result.ok !== true) {
        new Notice((result && result.message) || "Could not update the type");
        return;
      }
      await this.refreshManagerReport("write");
    } catch (error) {
      new Notice("Could not update the type");
    } finally {
      this.themeWriteInFlight = false;
    }
  }

  openThemeActions(row) {
    if (!row || row.kind !== "theme") {
      return false;
    }
    new PomodoroThemeActionModal(this.app, this, row).open();
    return true;
  }

  openThemeRename(row) {
    if (!row || row.kind !== "theme") {
      return;
    }
    new PomodoroThemeRenameModal(this.app, this, row.theme).open();
  }

  openThemeColor(row) {
    if (!row || row.kind !== "theme") {
      return;
    }
    if (row.theme && row.theme.hue_source === "config") {
      new Notice("Color set in ~/.config/bob/config.yml");
      return;
    }
    new PomodoroThemeColorModal(this.app, this, row.theme).open();
  }

  openThemeOccurrences(row) {
    if (!row || row.kind !== "theme") {
      return;
    }
    new PomodoroThemeOccurrencesModal(this.app, this.plugin, row.theme).open();
  }

  onClose() {
    stopNavigationPomodoroThemePicker(this);
    super.onClose();
  }
}

// ---- src/203-pomodoro-themes-manager-actions.js ----
// Pomodoro themes manager actions: action, color, occurrences, and rename
// modals plus the vault occurrence scan and the plugin mixin. Row models
// and the manager picker live in 202-pomodoro-themes-manager.js.

class PomodoroThemeActionModal extends FilteredPickerModal {
  constructor(app, manager, themeRow) {
    const theme = themeRow && themeRow.theme ? themeRow.theme : null;
    const name = theme && theme.name ? theme.name : "type";
    const hidden = theme && theme.hidden === true;
    const configColor = theme && theme.hue_source === "config";
    super(app, {
      items: [
        { kind: "action", key: "rename", title: `Rename ${name}`, meta: "Previewed one-commit rename (r)" },
        {
          kind: "action",
          key: "color",
          title: `Pin color for ${name}`,
          meta: configColor
            ? "Color set in ~/.config/bob/config.yml"
            : "8 hues plus Auto (c)",
          disabled: configColor,
          tooltip: configColor
            ? "Color set in ~/.config/bob/config.yml"
            : "",
        },
        { kind: "action", key: "hide", title: hidden ? `Unhide ${name}` : `Hide ${name}`, meta: "Recent suggestions only (h)" },
        { kind: "action", key: "occurrences", title: `Show occurrences of ${name}`, meta: "Daily notes, Enter opens (o)" },
      ],
      title: name,
      headerIcon: "timer",
      inputLabel: "Choose a type action",
      placeholder: "type to filter · r/c/h/o jump when empty",
      resultsLabel: "Type actions",
      emptyText: "No actions",
      footerHints: [
        { keys: ["r", "c", "h", "o"], label: "Jump to action" },
        { keys: ["↵"], label: "Run" },
        { keys: ["esc"], label: "Back" },
      ],
      filterItem: (row, query) => !query || String(row.title || "").toLowerCase().includes(query),
      renderItem: (row, rowEl, query) => {
        addPickerRowClasses(rowEl, [
          "bob-cnp-pomodoro-row",
          "is-action",
          row.disabled ? "is-disabled" : "",
        ]);
        if (row.disabled && typeof rowEl.setAttribute === "function") {
          rowEl.setAttribute("aria-disabled", "true");
          rowEl.setAttribute("title", row.tooltip || row.meta || "");
        }
        const iconEl = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
        applyIcon(iconEl, row.key === "rename" ? "pencil" : row.key === "color" ? "palette" : row.key === "hide" ? "eye-off" : "search");
        const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
        const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
        appendHighlighted(titleEl, row.title, query);
        const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
        if (row.disabled && typeof pathEl.setAttribute === "function") {
          pathEl.setAttribute("title", row.tooltip || row.meta || "");
        }
        appendHighlighted(pathEl, row.meta, query);
      },
      closeBeforeOpenItem: false,
      openItem: (row) => row && row.disabled ? false : this.runAction(row),
    });
    this.manager = manager;
    this.themeRow = themeRow;
  }

  handleKeydown(event) {
    // Single-key jumps stay out of the way of filtering: with text in the
    // filter input the keys type normally, and jump only when it is empty.
    if (this.inputEl && String(this.inputEl.value || "") !== "") {
      super.handleKeydown(event);
      return;
    }
    const key = String(event.key || "").toLowerCase();
    if (!event.ctrlKey && !event.metaKey && !event.altKey && ["r", "c", "h", "o"].includes(key)) {
      event.preventDefault();
      event.stopPropagation();
      const map = { r: "rename", c: "color", h: "hide", o: "occurrences" };
      const row = this.items.find((item) => item.key === map[key]);
      if (row) {
        void this.openItemAtIndex(this.items.indexOf(row));
      }
      return;
    }
    super.handleKeydown(event);
  }

  runAction(row) {
    if (!row || !this.manager) {
      return false;
    }
    if (row.disabled) {
      return false;
    }
    if (row.key === "rename") {
      this.manager.openThemeRename(this.themeRow);
    } else if (row.key === "color") {
      this.manager.openThemeColor(this.themeRow);
    } else if (row.key === "hide") {
      void this.manager.toggleThemeRowVisibility(this.themeRow);
    } else if (row.key === "occurrences") {
      this.manager.openThemeOccurrences(this.themeRow);
    }
    return true;
  }
}

class PomodoroThemeColorModal extends FilteredPickerModal {
  constructor(app, manager, theme) {
    const name = theme && theme.name ? theme.name : "type";
    const items = POMODORO_THEMES_MANAGER_HUES.map((hue, index) => ({
      kind: "color",
      key: `color-${hue}`,
      hue,
      label: `${index + 1} ${hue.slice(0, 1).toUpperCase()}${hue.slice(1)}`,
      meta: hue === (theme && theme.hue) ? "current" : "",
    }));
    items.push({ kind: "color", key: "color-auto", hue: "auto", label: "a Auto", meta: theme && theme.pinned === true ? "" : "current" });
    super(app, {
      items,
      title: `Pin color for ${name}`,
      headerIcon: "palette",
      inputLabel: "Choose a type color",
      placeholder: "type to filter · 1–8/a pin when empty",
      resultsLabel: "Type colors",
      emptyText: "No colors",
      footerHints: [
        { keys: ["1–8", "a"], label: "Pick hue or Auto" },
        { keys: ["↵"], label: "Pin" },
        { keys: ["esc"], label: "Back" },
      ],
      filterItem: (row, query) => !query || String(row.hue || "").includes(query),
      renderItem: (row, rowEl, query) => {
        addPickerRowClasses(rowEl, ["bob-cnp-pomodoro-row", "is-color"]);
        const swatchEl = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
        if (row.hue && row.hue !== "auto") {
          swatchEl.createDiv({ cls: `bob-cnp-theme-swatch is-${row.hue}` });
        } else {
          applyIcon(swatchEl, "rotate-ccw");
        }
        const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
        const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
        appendHighlighted(titleEl, row.label, query);
        if (row.meta) {
          const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
          appendHighlighted(pathEl, row.meta, query);
        }
      },
      closeBeforeOpenItem: false,
      openItem: (row) => {
        void this.pinColor(row);
        return false;
      },
    });
    this.manager = manager;
    this.theme = theme;
  }

  handleKeydown(event) {
    if (this.inputEl && String(this.inputEl.value || "") !== "") {
      super.handleKeydown(event);
      return;
    }
    const key = String(event.key || "").toLowerCase();
    if (!event.ctrlKey && !event.metaKey && !event.altKey && POMODORO_THEMES_MANAGER_COLOR_KEYS.includes(key)) {
      event.preventDefault();
      event.stopPropagation();
      const index = key === "a" ? this.items.length - 1 : Number(key) - 1;
      const row = this.items[index];
      if (row) {
        void this.pinColor(row);
      }
      return;
    }
    super.handleKeydown(event);
  }

  async pinColor(row) {
    if (!row || !this.manager || !this.manager.themesApi) {
      return;
    }
    const api = this.manager.themesApi;
    if (typeof api.color !== "function") {
      new Notice("Update bob to pin type colors");
      return;
    }
    try {
      const result = await api.color(this.theme.name, row.hue);
      if (!result || result.ok !== true) {
        new Notice((result && result.message) || "Could not pin the type color");
        return;
      }
      new Notice(row.hue === "auto" ? `${this.theme.name} uses its automatic hue` : `${this.theme.name} wears ${row.hue}`);
      this.close();
      await this.manager.refreshManagerReport("write");
    } catch (error) {
      new Notice("Could not pin the type color");
    }
  }
}

class PomodoroThemeOccurrencesModal extends FilteredPickerModal {
  constructor(app, plugin, theme, options = {}) {
    super(app, {
      items: [],
      title: `Occurrences of ${theme && theme.name ? theme.name : "type"}`,
      headerIcon: "search",
      inputLabel: "Filter occurrences",
      placeholder: "Filter daily notes",
      resultsLabel: "Type occurrences",
      emptyText: "Scanning daily notes…",
      footerHints: [
        { keys: ["↵"], label: "Open at entry" },
        { keys: ["esc"], label: "Back" },
      ],
      getSubtitle: () => this.occurrencesSubtitle(),
      filterItem: (row, query) => !query || `${row.path} ${row.tail}`.toLowerCase().includes(query),
      renderItem: (row, rowEl, query) => {
        addPickerRowClasses(rowEl, ["bob-cnp-pomodoro-row", "is-occurrence"]);
        const iconEl = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
        applyIcon(iconEl, "timer");
        const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
        const titleEl = textEl.createDiv({ cls: "bob-cnp-row-title" });
        appendHighlighted(titleEl, row.path, query);
        const pathEl = textEl.createDiv({ cls: "bob-cnp-row-path" });
        appendHighlighted(pathEl, row.tail, query);
      },
      closeBeforeOpenItem: true,
      openItem: (row) => {
        void this.openOccurrence(row);
        return false;
      },
    });
    this.plugin = plugin;
    this.theme = theme;
    this.opener = options && typeof options.opener === "function" ? options.opener : null;
    this.occurrencesError = null;
  }

  occurrencesSubtitle() {
    if (this.occurrencesError) {
      return this.occurrencesError;
    }
    const count = this.items.length;
    return `${count} ${count === 1 ? "occurrence" : "occurrences"}`;
  }

  onOpen() {
    super.onOpen();
    void this.loadOccurrences();
  }

  async loadOccurrences() {
    try {
      const rows = await findPomodoroThemeOccurrences(this.app, this.theme && this.theme.key);
      if (!this.pickerOpen) {
        return;
      }
      this.items = rows.map((row, index) => ({ kind: "occurrence", key: `occurrence-${index}`, ...row }));
      this.selectedIndex = 0;
      if (rows.length === 0) {
        this.emptyText = "No occurrences in daily notes";
      }
      this.renderResults();
    } catch (error) {
      this.occurrencesError = "Could not scan daily notes";
      this.emptyText = "Could not scan daily notes";
      this.renderResults();
    }
  }

  async openOccurrence(row) {
    if (!row || row.kind !== "occurrence") {
      return;
    }
    try {
      if (this.opener) {
        await this.opener(row);
        return;
      }
      const plugin = this.plugin;
      if (!plugin || typeof plugin.openMarkdownFileWithLeafReuse !== "function") {
        new Notice("Could not open the daily note");
        return;
      }
      const file = plugin.app && plugin.app.vault ? plugin.app.vault.getAbstractFileByPath(row.path) : null;
      if (!file) {
        new Notice("Daily note is no longer in the vault");
        return;
      }
      const opened = await plugin.openMarkdownFileWithLeafReuse(file, "Could not open the daily note");
      if (!opened) {
        return;
      }
      const view = typeof plugin.getActiveMarkdownView === "function" ? plugin.getActiveMarkdownView() : null;
      const editor = view && view.editor ? view.editor : null;
      if (editor && typeof setEditorCursor === "function") {
        setEditorCursor(editor, { line: row.line, ch: 0 });
      }
    } catch (error) {
      new Notice("Could not open the daily note");
    }
  }
}

// Scan the vault's canonical daily notes for entries containing the theme
// key. Reads through the vault cache so the scan stays cheap.
async function findPomodoroThemeOccurrences(app, key) {
  const wanted = normalizePomodoroThemeManagerKey(key);
  if (!wanted) {
    return [];
  }
  const vault = app && app.vault ? app.vault : null;
  if (!vault || typeof vault.getMarkdownFiles !== "function") {
    return [];
  }
  const files = vault.getMarkdownFiles().filter((file) => file && isPomodoroThemeManagerDailyPath(file.path));
  files.sort((left, right) => (left.path < right.path ? 1 : left.path > right.path ? -1 : 0));
  const rows = [];
  for (const file of files) {
    try {
      const content =
        typeof vault.cachedRead === "function"
          ? await vault.cachedRead(file)
          : typeof vault.read === "function"
            ? await vault.read(file)
            : "";
      for (const row of collectPomodoroThemeOccurrencesInText(file.path, content, wanted)) {
        rows.push(row);
      }
    } catch (error) {
      continue;
    }
  }
  return rows;
}

class PomodoroThemeRenameModal extends Modal {
  constructor(app, manager, theme) {
    super(app);
    this.manager = manager;
    this.theme = theme;
    this.renamePreview = null;
    this.renameError = null;
    this.renameApplying = false;
  }

  onOpen() {
    this.contentEl.empty();
    this.modalEl.addClass("bob-cnp-modal");
    this.contentEl.addClass("bob-cnp");
    const header = this.contentEl.createDiv({ cls: "bob-cnp-header" });
    const headerIcon = header.createDiv({ cls: "bob-cnp-header-icon" });
    applyIcon(headerIcon, "pencil");
    const headerText = header.createDiv({ cls: "bob-cnp-header-text" });
    const title = headerText.createDiv({ cls: "bob-cnp-title" });
    const from = this.theme && this.theme.name ? this.theme.name : "type";
    title.setText(`Rename ${from}`);
    const subtitle = headerText.createDiv({ cls: "bob-cnp-subtitle" });
    subtitle.setText("Previewed one-commit rename across daily notes");

    const form = this.contentEl.createDiv({ cls: "bob-cnp-rename-form" });
    form.createEl("label", { cls: "bob-cnp-rename-label", text: "New name" });
    this.nameInput = form.createEl("input", {
      cls: "bob-cnp-input",
      attr: { type: "text", placeholder: "FIX", "aria-label": "New type name" },
    });
    this.mergeToggle = form.createEl("input", {
      cls: "bob-cnp-rename-merge",
      attr: { type: "checkbox", "aria-label": "Merge into an existing type" },
    });
    form.createEl("label", { cls: "bob-cnp-rename-label", text: "Merge into an existing type (--merge)" });

    const buttons = this.contentEl.createDiv({ cls: "bob-cnp-rename-buttons" });
    this.previewButton = buttons.createEl("button", { cls: "bob-cnp-rename-button", text: "Preview" });
    this.applyButton = buttons.createEl("button", { cls: "bob-cnp-rename-button", text: "Rename" });
    this.previewButton.addEventListener("click", () => void this.previewRename());
    this.applyButton.addEventListener("click", () => void this.applyRename());
    this.nameInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        void this.previewRename();
      }
    });

    this.previewEl = this.contentEl.createDiv({ cls: "bob-cnp-results" });
    window.setTimeout(() => {
      if (this.nameInput && typeof this.nameInput.focus === "function") {
        this.nameInput.focus();
      }
    }, 0);
  }

  renameTarget() {
    return String((this.nameInput && this.nameInput.value) || "");
  }

  async previewRename() {
    this.renameError = null;
    const error = pomodoroThemesManagerRenameInputError(this.renameTarget());
    if (error) {
      this.renameError = error;
      this.renderRenamePreview();
      return null;
    }
    const api = this.manager && this.manager.themesApi;
    if (!api || typeof api.rename !== "function") {
      this.renameError = "Type renames need the desktop app.";
      this.renderRenamePreview();
      return null;
    }
    const merge = Boolean(this.mergeToggle && this.mergeToggle.checked);
    try {
      const result = await api.rename(this.theme.name, this.renameTarget().trim().toUpperCase(), { dryRun: true, merge });
      if (!result || result.ok !== true) {
        this.renameError = (result && result.message) || "Could not preview the rename";
        if (result && result.code === "theme_exists") {
          this.renameError += " — tick merge to combine";
        }
        this.renamePreview = null;
        this.renderRenamePreview();
        return null;
      }
      this.renamePreview = formatPomodoroThemeManagerRenamePreview(result.report || result);
      this.renderRenamePreview();
      return this.renamePreview;
    } catch (error) {
      this.renameError = "Could not preview the rename";
      this.renderRenamePreview();
      return null;
    }
  }

  renderRenamePreview() {
    if (!this.previewEl) {
      return;
    }
    this.previewEl.empty();
    if (this.renameError) {
      const errorEl = this.previewEl.createDiv({ cls: "bob-cnp-empty" });
      errorEl.createDiv({ cls: "bob-cnp-empty-text", text: this.renameError });
      return;
    }
    if (!this.renamePreview) {
      const hintEl = this.previewEl.createDiv({ cls: "bob-cnp-empty" });
      hintEl.createDiv({ cls: "bob-cnp-empty-text", text: "Preview shows the notes, entries, and color change before anything writes." });
      return;
    }
    const titleEl = this.previewEl.createDiv({ cls: "bob-cnp-row-title" });
    titleEl.setText(this.renamePreview.title);
    for (const line of this.renamePreview.lines) {
      const rowEl = this.previewEl.createDiv({ cls: "bob-cnp-row" });
      const textEl = rowEl.createDiv({ cls: "bob-cnp-row-text" });
      textEl.createDiv({ cls: "bob-cnp-row-path", text: line });
    }
    if (this.renamePreview.stateNote || this.renamePreview.colorNote) {
      const noteEl = this.previewEl.createDiv({ cls: "bob-cnp-row-path" });
      noteEl.setText([this.renamePreview.stateNote, this.renamePreview.colorNote].filter(Boolean).join(" · "));
    }
  }

  async applyRename() {
    if (this.renameApplying) {
      return;
    }
    const preview = this.renamePreview || (await this.previewRename());
    if (!preview) {
      return;
    }
    const api = this.manager && this.manager.themesApi;
    if (!api || typeof api.rename !== "function") {
      new Notice("Type renames need the desktop app.");
      return;
    }
    const to = this.renameTarget().trim().toUpperCase();
    const merge = Boolean(this.mergeToggle && this.mergeToggle.checked);
    this.renameApplying = true;
    try {
      const saved = await this.saveOpenThemeNotes(preview);
      if (!saved) {
        new Notice("Save the listed notes first, then rename again");
        return;
      }
      const result = await api.rename(this.theme.name, to, { merge });
      if (!result || result.ok !== true) {
        new Notice((result && result.message) || "Could not rename the type");
        return;
      }
      const files = preview.files;
      new Notice(`Renamed ${this.theme.name} → ${to} in ${files} ${files === 1 ? "note" : "notes"} · one commit`);
      this.close();
      if (this.manager) {
        await this.manager.refreshManagerReport("rename");
      }
    } catch (error) {
      new Notice("Could not rename the type");
    } finally {
      this.renameApplying = false;
    }
  }

  // Save every open editor whose note the rename touches. A failed save
  // refuses the rename instead of writing under an unsaved buffer.
  async saveOpenThemeNotes(preview) {
    try {
      const app = this.manager && this.manager.app ? this.manager.app : this.app;
      const workspace = app && app.workspace ? app.workspace : null;
      if (!workspace) {
        return true;
      }
      const touched = new Set((preview && preview.lines ? preview.lines : []).map((line) => String(line).split(" · ")[0]));
      const leaves = [];
      if (typeof workspace.iterateAllLeaves === "function") {
        workspace.iterateAllLeaves((leaf) => leaves.push(leaf));
      } else if (typeof workspace.getLeavesOfType === "function") {
        for (const type of ["markdown", "editor"]) {
          try {
            for (const leaf of workspace.getLeavesOfType(type)) {
              leaves.push(leaf);
            }
          } catch (error) {
            continue;
          }
        }
      }
      for (const leaf of leaves) {
        const view = leaf && leaf.view ? leaf.view : null;
        const file = view && view.file ? view.file : null;
        if (!file || !touched.has(file.path)) {
          continue;
        }
        if (view && typeof view.save === "function") {
          try {
            await view.save();
          } catch (error) {
            return false;
          }
        }
      }
      return true;
    } catch (error) {
      return false;
    }
  }

  onClose() {
    this.modalEl.removeClass("bob-cnp-modal");
    this.contentEl.empty();
  }
}

class BobNavigationHotkeysPomodoroThemesManagerMixin {
  openPomodoroThemesManager() {
    const api = getNavigationPomodoroThemesApi(this.app);
    if (!navigationPomodoroThemeAvailable(api)) {
      new Notice("Task types need the desktop app.");
      return false;
    }
    try {
      new PomodoroThemesManagerModal(this.app, this).open();
      return true;
    } catch (error) {
      new Notice("Could not open task types");
      return false;
    }
  }
}
// ---- src/205-inbox-route-picker-modal.js ----
// Inbox route picker modal (route-core): asks where an inbox task goes as
// the last step before a Ctrl+Shift+P or Ctrl+Shift+Enter write. Built on
// `FilteredPickerModal` and reuses the Ctrl+Shift+M destination rows so the
// two pickers look like siblings. Resolves a promise exactly once with
// `{ kind: "move", file }`, `{ kind: "stay" }`, or `{ kind: "cancel" }`;
// closing without a choice means cancel. `↵` preflights the move first: a
// refusal keeps the picker open with a Notice so another destination can be
// chosen. `⇧↵` applies in place (stay) and `Esc` / `Ctrl+[` backs out.
// Uses the default `closeBeforeOpenItem: false` and closes itself after
// resolving. Registers in the shared `activeTaskMoveDestinationPicker`
// guard, so Ctrl+Shift+M and a second route cannot open on top of it.
class InboxRoutePickerModal extends FilteredPickerModal {
  constructor(app, plugin, options = {}) {
    const destinations = Array.isArray(options.destinations)
      ? options.destinations
      : [];
    const actionLabel = formatInboxRouteActionLabel(options.actionLabel);
    const backLabel = options.cancelLabel === "cancel" ? "cancel" : "back";
    super(app, {
      items: destinations,
      title: `Route out of ${options.inboxName || "inbox"}`,
      headerIcon: "inbox",
      inputLabel: "Filter route destinations",
      placeholder: "Where does this go? Filter areas and open projects",
      resultsLabel: "Route destinations",
      emptyText: "No matching areas or open projects",
      getSubtitle: () =>
        formatInboxRouteTaskSubtitle({
          taskText: options.taskText,
          count: options.count,
          actionLabel,
        }),
      filterItem: (entry, query) =>
        childNoteMatchesQuery(entry.file, entry.noteInfo, query),
      renderItem: (entry, rowEl, query) =>
        renderTypedNotePickerRow(entry.file, entry.noteInfo, rowEl, query),
      closeBeforeOpenItem: false,
      footerHints: [
        { keys: ["↵"], label: `move & ${actionLabel}` },
        { keys: ["⇧", "↵"], label: "keep in inbox" },
        { keys: ["esc"], label: backLabel },
      ],
      openItem: (entry) => this.chooseRouteDestination(entry),
    });
    this.inboxRoutePlugin = plugin;
    this.inboxRouteSettled = false;
    this.inboxRouteResolve = null;
    this.inboxRouteResult = new Promise((resolve) => {
      this.inboxRouteResolve = resolve;
    });
    this.inboxRoutePreflight =
      typeof options.preflight === "function" ? options.preflight : null;
  }

  waitForRoute() {
    return this.inboxRouteResult;
  }

  settleRoute(outcome) {
    if (this.inboxRouteSettled) {
      return;
    }
    this.inboxRouteSettled = true;
    let result = { kind: "cancel" };
    if (outcome && outcome.kind === "move" && outcome.file) {
      result = { kind: "move", file: outcome.file };
    } else if (outcome && outcome.kind === "stay") {
      result = { kind: "stay" };
    }
    try {
      this.inboxRouteResolve(result);
    } catch (error) {
      // The awaiting gate owns recovery; the resolve is best-effort.
    }
    if (this.pickerOpen) {
      try {
        this.close();
      } catch (error) {
        // Closing is best-effort after resolving.
      }
    }
  }

  async chooseRouteDestination(entry) {
    if (!entry || !entry.file) {
      return false;
    }
    let check = { ok: true, reason: null };
    try {
      if (this.inboxRoutePreflight) {
        check = (await this.inboxRoutePreflight(entry.file)) || check;
      }
    } catch (error) {
      check = { ok: false, reason: "Route preflight failed" };
    }
    if (!check || check.ok !== true) {
      new Notice(
        check && check.reason ? check.reason : "Destination is no longer eligible",
      );
      return false;
    }
    this.settleRoute({ kind: "move", file: entry.file });
    return true;
  }

  chooseRouteStay() {
    this.settleRoute({ kind: "stay" });
  }

  handleKeydown(event) {
    if (event && event.key === "Enter" && event.shiftKey === true) {
      event.preventDefault();
      event.stopPropagation();
      this.chooseRouteStay();
      return;
    }
    if (event && isCtrlKey(event, "[")) {
      event.preventDefault();
      event.stopPropagation();
      this.settleRoute({ kind: "cancel" });
      return;
    }
    super.handleKeydown(event);
  }

  onClose() {
    if (
      this.inboxRoutePlugin &&
      this.inboxRoutePlugin.activeTaskMoveDestinationPicker === this
    ) {
      this.inboxRoutePlugin.activeTaskMoveDestinationPicker = null;
    }
    this.settleRoute({ kind: "cancel" });
    super.onClose();
  }
}
// ---- src/206a-successor-picker-model.js ----
// Pure successor-picker model helpers: destination/intent normalizers,
// optional per-row task context, and a preimage-checked note refresh used
// before the nested destination picker. Shared scope with
// 206-successor-picker-modal.js.

// Strict validation for additive themeIntent on a destination override.
// Malformed intent is dropped so it can never enable a write; absent
// intent keeps the legacy destination shape. linkOnce always wins over
// deliberate, matching the picker (Alt+Enter is never a theme write).
function normalizeSuccessorThemeIntent(intent) {
  try {
    if (!intent || typeof intent !== "object" || Array.isArray(intent)) {
      return null;
    }
    if (typeof intent.deliberate !== "boolean") {
      return null;
    }
    if (typeof intent.linkOnce !== "boolean") {
      return null;
    }
    let shown = null;
    if (intent.shown === undefined || intent.shown === null) {
      shown = null;
    } else if (typeof intent.shown !== "object") {
      return null;
    } else {
      const theme = intent.shown.theme;
      if (!theme || typeof theme !== "object") {
        return null;
      }
      if (typeof theme.key !== "string" || !theme.key) {
        return null;
      }
      shown = intent.shown;
    }
    const linkOnce = intent.linkOnce === true;
    return Object.freeze({
      deliberate: linkOnce ? false : intent.deliberate,
      linkOnce,
      shown,
    });
  } catch (_error) {
    return null;
  }
}

// Per-row destination override (docs/task-dependencies.md §12.13,
// obsidian_destination): `{kind: "existing", entryLine, entryText, title?} |
// {kind: "new", name, preserveSpelling?}`. Optional `themeIntent` rides
// along when valid. Null unless the destination shape is exact.
function normalizeSuccessorDestinationOverride(choice) {
  try {
    if (!choice || typeof choice !== "object") {
      return null;
    }
    const themeIntent = normalizeSuccessorThemeIntent(choice.themeIntent);
    if (choice.kind === "existing") {
      if (!Number.isInteger(choice.entryLine) || choice.entryLine < 0) {
        return null;
      }
      if (typeof choice.entryText !== "string" || !choice.entryText) {
        return null;
      }
      const title = typeof choice.title === "string" ? choice.title.trim() : "";
      return Object.freeze({
        kind: "existing",
        entryLine: choice.entryLine,
        entryText: choice.entryText,
        ...(title ? { title } : {}),
        ...(themeIntent ? { themeIntent } : {}),
      });
    }
    if (choice.kind === "new") {
      const name = typeof choice.name === "string" ? choice.name.trim() : "";
      if (!name || /[\r\n]/.test(name)) {
        return null;
      }
      return Object.freeze({
        kind: "new",
        name,
        ...(choice.preserveSpelling === true ? { preserveSpelling: true } : {}),
        ...(themeIntent ? { themeIntent } : {}),
      });
    }
    return null;
  } catch (_error) {
    return null;
  }
}

function successorDestinationOverrideLabel(destination) {
  try {
    if (!destination || typeof destination !== "object") {
      return "";
    }
    if (destination.kind === "new") {
      return typeof destination.name === "string" ? destination.name.trim() : "";
    }
    if (destination.kind === "existing") {
      if (typeof destination.title === "string" && destination.title.trim()) {
        return destination.title.trim();
      }
      if (typeof destination.name === "string" && destination.name.trim()) {
        return destination.name.trim();
      }
      if (Number.isInteger(destination.entryLine)) {
        return `line ${destination.entryLine + 1}`;
      }
    }
    return "";
  } catch (_error) {
    return "";
  }
}

// Defensive feature detection for block-id-prompt
// `api.pomodoroLinkPicker` v1 (§12.13). Null when the plugin is missing,
// older, or torn down.
function getSuccessorDestinationPickerApi(app) {
  try {
    const plugins = (app && app.plugins && app.plugins.plugins) || {};
    const prompt = plugins["block-id-prompt"];
    const api = prompt && prompt.api;
    const picker = api && api.pomodoroLinkPicker;
    if (!picker || !(Number(picker.version) >= 1)) {
      return null;
    }
    if (typeof picker.pick !== "function") {
      return null;
    }
    return picker;
  } catch (_error) {
    return null;
  }
}

function successorPickerText(value) {
  return typeof value === "string" ? value.trim() : "";
}

function successorPickerCount(value) {
  return Number.isFinite(Number(value)) && Number(value) >= 0
    ? Math.floor(Number(value))
    : 0;
}

function successorPickerNoteName(path) {
  const value = successorPickerText(path);
  const leaf = value.split("/").pop() || value;
  return leaf.toLowerCase().endsWith(".md") ? leaf.slice(0, -3) : leaf;
}

// Optional validated task context for `api.pick({task})`. `line` is
// one-based and `text` is the full note. `preimage` is the original task
// line used to refuse a changed/missing source before the nested picker.
// Malformed context is dropped so older row shapes stay selectable.
function normalizeSuccessorPickerTaskContext(task) {
  try {
    if (!task || typeof task !== "object") {
      return null;
    }
    const path = typeof task.path === "string" ? task.path : "";
    if (!path) {
      return null;
    }
    if (!Number.isInteger(task.line) || task.line < 1) {
      return null;
    }
    if (typeof task.text !== "string") {
      return null;
    }
    if (typeof task.preimage !== "string") {
      return null;
    }
    const displayText = typeof task.displayText === "string" ? task.displayText : "";
    const status = typeof task.status === "string" ? task.status : "";
    return Object.freeze({
      path,
      line: task.line,
      text: task.text,
      displayText,
      status,
      preimage: task.preimage,
    });
  } catch (_error) {
    return null;
  }
}

function normalizeSuccessorPickerModel(model) {
  try {
    if (!model || typeof model !== "object" || !Array.isArray(model.groups)) {
      return null;
    }
    const allowedGroups = new Set(["hand_off", "project", "project_finished"]);
    const seenKeys = new Set();
    const groups = [];
    let selectableCount = 0;
    let taskRowCount = 0;
    for (const source of model.groups) {
      if (!source || typeof source !== "object" || !allowedGroups.has(source.group)) {
        continue;
      }
      const rows = [];
      for (const row of Array.isArray(source.rows) ? source.rows : []) {
        if (!row || typeof row !== "object") {
          continue;
        }
        const key = typeof row.key === "string" ? row.key : "";
        const text = successorPickerText(row.text);
        if (!key || !text || seenKeys.has(key)) {
          if (key && seenKeys.has(key)) {
            return null;
          }
          continue;
        }
        if (typeof row.notePath !== "string" || typeof row.selectable !== "boolean") {
          continue;
        }
        const task = normalizeSuccessorPickerTaskContext(row.task);
        const normalized = Object.freeze({
          key,
          text,
          notePath: row.notePath,
          status: successorPickerText(row.status),
          destinationLabel: successorPickerText(row.destinationLabel),
          needsBlockId: row.needsBlockId === true,
          selectable: row.selectable,
          mutedReason: successorPickerText(row.mutedReason),
          destination: row.destination,
          ...(task ? { task } : {}),
        });
        seenKeys.add(key);
        rows.push(normalized);
        taskRowCount += 1;
        if (normalized.selectable) {
          selectableCount += 1;
        }
      }
      const folded = source.folded && typeof source.folded === "object"
        ? Object.freeze({
            hidden: successorPickerCount(source.folded.hidden),
            alreadyPlanned: successorPickerCount(source.folded.alreadyPlanned),
            subProjects: successorPickerCount(source.folded.subProjects),
          })
        : Object.freeze({ hidden: 0, alreadyPlanned: 0, subProjects: 0 });
      groups.push(Object.freeze({
        group: source.group,
        header: successorPickerText(source.header),
        project: successorPickerText(source.project),
        rows: Object.freeze(rows),
        folded,
      }));
    }
    if (selectableCount === 0 || groups.length === 0) {
      return null;
    }
    const budget = model.budget && typeof model.budget === "object"
      ? Object.freeze({
          links: successorPickerCount(model.budget.links),
          max: successorPickerCount(model.budget.max),
        })
      : null;
    const predecessors = Array.isArray(model.predecessors)
      ? model.predecessors.filter((row) => row && typeof row === "object").map((row) => Object.freeze({
          notePath: successorPickerText(row.notePath),
          blockId: successorPickerText(row.blockId),
          text: successorPickerText(row.text),
        }))
      : [];
    return Object.freeze({
      title: successorPickerText(model.title) || "Choose successor tasks",
      predecessors: Object.freeze(predecessors),
      groups: Object.freeze(groups),
      budget,
      selectableCount,
      taskRowCount,
    });
  } catch (_error) {
    return null;
  }
}

// Live note text for a vault-relative path: open editor buffers first,
// then the vault. Null when the note cannot be read, including
// ambiguous open buffers.
async function readSuccessorPickerNoteText(app, path) {
  try {
    const normalized = normalizeVaultRelativePath(path);
    if (!normalized) {
      return null;
    }
    const buffers = getOpenMarkdownBufferContents(app);
    if (buffers.ambiguous) {
      return null;
    }
    if (buffers.has(normalized)) {
      return String(buffers.get(normalized) || "");
    }
    const vault = app && app.vault;
    const file = vault && typeof vault.getAbstractFileByPath === "function"
      ? vault.getAbstractFileByPath(normalized)
      : null;
    if (!vault || !file) {
      return null;
    }
    if (typeof vault.cachedRead === "function") {
      return String((await vault.cachedRead(file)) || "");
    }
    if (typeof vault.read === "function") {
      return String((await vault.read(file)) || "");
    }
    return null;
  } catch (_error) {
    return null;
  }
}

async function refreshSuccessorPickerTaskContext(app, task) {
  try {
    const normalized = normalizeSuccessorPickerTaskContext(task);
    if (!normalized) {
      return null;
    }
    const liveText = await readSuccessorPickerNoteText(app, normalized.path);
    if (typeof liveText !== "string") {
      return null;
    }
    const lines = liveText.split(/\r?\n/);
    const index = normalized.line - 1;
    if (index < 0 || index >= lines.length) {
      return null;
    }
    if (lines[index] !== normalized.preimage) {
      return null;
    }
    return Object.freeze({
      path: normalized.path,
      line: normalized.line,
      text: liveText,
      displayText: normalized.displayText,
      status: normalized.status,
      preimage: normalized.preimage,
    });
  } catch (_error) {
    return null;
  }
}

function successorPickerTaskPickRequest(task) {
  if (!task) {
    return {};
  }
  return {
    task: {
      path: task.path,
      line: task.line,
      text: task.text,
      displayText: task.displayText,
      status: task.status,
    },
  };
}

// Marked selectable rows in displayed (model) order, else the highlighted
// row. Never reconstructs identity from display text or the opaque key.
function successorPickerRetargetRows(modal) {
  const rows = [];
  try {
    if (!modal || !modal.model) {
      return rows;
    }
    if (modal.markedKeys && modal.markedKeys.size > 0) {
      for (const group of modal.model.groups) {
        for (const row of group.rows) {
          if (row.selectable && modal.markedKeys.has(row.key)) {
            rows.push(row);
          }
        }
      }
      return rows;
    }
    const active = modal.visibleItems && modal.visibleItems[modal.selectedIndex];
    if (active && active.kind === "offer" && active.row && active.row.selectable) {
      rows.push(active.row);
    }
  } catch (_error) {
    return [];
  }
  return rows;
}
