// Shared data-only closing preview for phase .7. Callers pass the complete
// pending edge sets so mixed actions and Linked-from use the same planner.
class BulletPropertyPickerRelationClosePreviewMixin {
  relationClosePreviewForChanges(args = {}) {
    const loaded = args.closeLabels || this.relationCloseLabelsConfig();
    const cancelLabels = args.cancelLabels !== undefined
      ? args.cancelLabels
      : loaded.cancel;
    const completeLabels = args.completeLabels !== undefined
      ? args.completeLabels
      : loaded.complete;
    const trigger = args.trigger || RELATION_CANCEL_EXPLICIT_TRIGGER;
    const day = args.date || formatBulletPropertyDate(new Date());
    const sources = Array.isArray(args.sources) ? args.sources : [];
    const add = Array.isArray(args.add) ? args.add : [];
    const remove = Array.isArray(args.remove) ? args.remove : [];
    const relabel = Array.isArray(args.relabel)
      ? args.relabel
      : args.relabel && typeof args.relabel === "object"
        ? Object.entries(args.relabel).map(([path, label]) => ({ target: path, label }))
        : [];
    const vaultEntries =
      this.plugin && typeof this.plugin.readDependencyVaultFileList === "function"
        ? this.plugin.readDependencyVaultFileList()
        : this.vaultStage && this.vaultStage.files instanceof Map
          ? [...this.vaultStage.files.keys()]
          : [];
    const vaultFiles = (Array.isArray(vaultEntries) ? vaultEntries : []).map((entry) =>
      typeof entry === "string" ? { path: entry } : entry,
    );
    const resolveLinkpath =
      this.plugin && typeof this.plugin.dependencyLinkpathResolver === "function"
        ? this.plugin.dependencyLinkpathResolver()
        : null;
    const api = relationTaskStatusCyclerApi(this.plugin && this.plugin.app);
    const plans = [];
    for (const sourceRef of sources) {
      const path = normalizeVaultRelativePath(sourceRef && sourceRef.path);
      const content = this.relationCancelContentForRef({ ...sourceRef, path });
      const lines = content.split(/\r?\n/);
      let line = Math.floor(numericOrDefault(sourceRef && sourceRef.line, NaN));
      const blockId = normalizeBulletPropertyValue(sourceRef && sourceRef.blockId);
      if (blockId) {
        const found = findTaskLineByTrailingBlockId(lines, blockId);
        if (found !== null) line = found;
      }
      if (!Number.isInteger(line) || line < 0 || line >= lines.length) {
        return Object.freeze({ ok: false, reason: "source-not-found" });
      }
      const rawLine = String(lines[line] || "");
      const children = findLinksChildren(lines, line);
      const existingRows = children.flatMap((index) =>
        relationLinksRows(path, lines[index], resolveLinkpath, vaultFiles),
      );
      const normalizeTarget = (entry) => {
        const raw = entry && entry.target ? { ...entry.target, label: entry.label } : entry;
        const targetPath = normalizeVaultRelativePath(raw && raw.path);
        const targetContent = this.relationCancelContentForRef({ ...raw, path: targetPath });
        const targetLines = targetContent.split(/\r?\n/);
        let targetLine = Math.floor(numericOrDefault(raw && raw.line, NaN));
        const targetId = normalizeBulletPropertyValue(raw && (raw.blockId || raw.existingBlockId));
        if (targetId) {
          const found = findTaskLineByTrailingBlockId(targetLines, targetId);
          if (found !== null) targetLine = found;
        }
        if (!Number.isInteger(targetLine) || targetLine < 0 || targetLine >= targetLines.length) {
          return null;
        }
        return Object.freeze({
          ...raw,
          path: targetPath,
          line: targetLine,
          blockId: getTrailingBlockId(targetLines[targetLine]) || targetId,
          rawLine: targetLines[targetLine],
          description: relationNoticeNameFromLine(targetLines[targetLine]),
        });
      };
      const liveAdd = add.map(normalizeTarget).filter(Boolean);
      const liveRemove = remove.map(normalizeTarget).filter(Boolean);
      const liveRelabel = relabel.map(normalizeTarget).filter(Boolean);
      const planned = planLinksEdit(content, line, {
        add: liveAdd.map((target) => ({
          link: storedRelationLinkForTarget(existingRows, target, path, vaultFiles),
          label: target.label,
        })),
        remove: liveRemove.map((target) =>
          storedRelationLinkForTarget(existingRows, target, path, vaultFiles),
        ),
        relabel: liveRelabel.map((target) => ({
          link: storedRelationLinkForTarget(existingRows, target, path, vaultFiles),
          label: target.label,
        })),
      });
      if (!planned.ok) return Object.freeze({ ok: false, reason: planned.reason });
      const edges = deriveRelationCancelEdges({
        report: planned.report,
        existingRows,
        liveAdd,
        liveRelabel,
        sourcePath: path,
        vaultFiles,
      });
      const policySource = relationCancelPolicySourceFromLine(
        {
          path,
          line,
          blockId: getTrailingBlockId(rawLine) || blockId,
        },
        rawLine,
        edges,
      );
      plans.push(
        planRelationClosingSource({
          cancelLabels,
          completeLabels,
          trigger,
          cyclerApiAvailable: relationCompleteCyclerApiAvailable(api),
          source: policySource,
        }),
      );
    }
    const cancelSources = plans.map((entry) => entry.cancel).filter(Boolean);
    const completeSources = plans.map((entry) => entry.complete).filter(Boolean);
    const cancelRefusals = plans.map((entry) => entry.cancelRefusal).filter(Boolean);
    const completeRefusals = plans.map((entry) => entry.completeRefusal).filter(Boolean);
    const cancelPlan = {
      sources: cancelSources,
      cancels: cancelSources.filter((entry) => entry.cancels),
      refusals: cancelRefusals,
    };
    const completePlan = {
      sources: completeSources,
      completes: completeSources.filter((entry) => entry.completes),
      refusals: completeRefusals,
    };
    const gate = relationCloseCommitGate({
      cancelSourcePlans: cancelSources,
      cancelRefusals,
      completePlan,
      day,
    });
    this.relationCloseExpected = gate.closeEffects;
    return Object.freeze({
      ok: true,
      cancel: Object.freeze(cancelPlan),
      complete: Object.freeze(completePlan),
      cancelEffects: gate.cancelEffects,
      closeEffects: gate.closeEffects,
      expected: gate.closeEffects,
      expectedCloseEffects: gate.closeEffects,
      expectedCancelEffects: gate.cancelEffects,
      refusal: gate.ok ? null : Object.freeze({ reason: gate.reason, notice: gate.notice }),
    });
  }
}
// ---- src/429-relation-label-management.js ----
function getNavigationRelationLabelsApi(app) {
  try {
    const plugins = app && app.plugins && app.plugins.plugins;
    const holder = plugins && plugins["bob-ledger-tools"];
    const api = holder && holder.api && holder.api.relationLabels;
    return api && Number(api.version) >= 1 ? api : null;
  } catch (_error) {
    return null;
  }
}

function relationLabelRenameInputError(raw) {
  const label = normalizeRelationLabel(String(raw || ""));
  if (label) return null;
  return describeRelationLabelRefusal(raw) || "Enter a valid relation label.";
}

function relationLabelRenameReport(result) {
  return result && result.report && typeof result.report === "object"
    ? result.report
    : result && typeof result === "object"
      ? result
      : null;
}

function formatRelationLabelRenamePreview(result) {
  const report = relationLabelRenameReport(result);
  if (!report) {
    return {
      title: "No rename preview",
      lines: [],
      links: 0,
      notes: 0,
      mirrors: 0,
      doneLinks: 0,
      merge: false,
    };
  }
  const files = Array.isArray(report.files) ? report.files : [];
  const counts = report.counts && typeof report.counts === "object" ? report.counts : {};
  const links = Math.max(0, Number(counts.links) || 0);
  const notes = Math.max(0, Number(counts.notes) || files.length);
  const mirrors = Math.max(0, Number(counts.mirrors) || 0);
  const doneLinks = Math.max(0, Number(counts.done_links) || 0);
  const from = report.from && report.from.name ? String(report.from.name) : "relation";
  const to = report.to && report.to.name ? String(report.to.name) : "new label";
  const lines = files.map((file) => {
    const path = String(file && file.path || "");
    const fileLinks = Math.max(0, Number(file && file.links) || 0);
    const fileMirrors = Math.max(0, Number(file && file.mirrors) || 0);
    const parts = [
      `${fileLinks} ${fileLinks === 1 ? "link" : "links"}`,
      `${fileMirrors} ${fileMirrors === 1 ? "mirror" : "mirrors"}`,
    ];
    const edits = Array.isArray(file && file.lines) ? file.lines : [];
    return `${path} · ${parts.join(" · ")}${edits.length ? ` · ${edits.length} changed ${edits.length === 1 ? "line" : "lines"}` : ""}`;
  });
  const doneNote = doneLinks > 0 ? ` · ${doneLinks} in done/` : "";
  return {
    title: `${from} → ${to} · ${links} ${links === 1 ? "link" : "links"} in ${notes} ${notes === 1 ? "note" : "notes"} · ${mirrors} ${mirrors === 1 ? "mirror" : "mirrors"}${doneNote}`,
    lines,
    links,
    notes,
    mirrors,
    doneLinks,
    merge: report.merge === true,
    stateNote: report.state && report.state.note ? String(report.state.note) : "",
    inverseNote: report.inverse && report.inverse.note ? String(report.inverse.note) : "",
    warnings: Array.isArray(report.warnings) ? report.warnings.map(String) : [],
  };
}

function relationLabelRenamePreviewSignature(result) {
  const report = relationLabelRenameReport(result);
  if (!report) return "";
  return JSON.stringify({
    from: report.from,
    to: report.to,
    merge: report.merge === true,
    files: report.files,
    counts: report.counts,
    state: report.state,
    inverse: report.inverse,
    replacement: report.replacement,
    hide_replacement: report.hide_replacement,
  });
}

function relationLabelRenameFilePaths(result) {
  const report = relationLabelRenameReport(result);
  return [...new Set((Array.isArray(report && report.files) ? report.files : [])
    .map((file) => String(file && file.path || "").trim())
    .filter(Boolean))];
}

async function saveActiveRelationLabelEditor(app) {
  try {
    const workspace = app && app.workspace;
    if (!workspace) return { ok: true };
    let view = null;
    if (typeof workspace.getActiveViewOfType === "function") {
      try {
        view = workspace.getActiveViewOfType(MarkdownView);
      } catch (_error) {
        view = null;
      }
    }
    if (!view && workspace.activeLeaf) view = workspace.activeLeaf.view || null;
    if (!view || !view.file || !view.editor) return { ok: true };
    if (typeof view.save !== "function") {
      return { ok: false, message: "Could not save the active note before previewing the rename." };
    }
    await view.save();
    return { ok: true };
  } catch (_error) {
    return { ok: false, message: "Could not save the active note before previewing the rename." };
  }
}

async function relationLabelDirtyEditorPaths(app, result) {
  const touched = new Set(relationLabelRenameFilePaths(result));
  if (!touched.size) return [];
  const workspace = app && app.workspace;
  const vault = app && app.vault;
  if (!workspace || !vault) return [];
  const leaves = [];
  try {
    if (typeof workspace.iterateAllLeaves === "function") {
      workspace.iterateAllLeaves((leaf) => leaves.push(leaf));
    } else if (typeof workspace.getLeavesOfType === "function") {
      for (const type of ["markdown", "editor"]) {
        try {
          for (const leaf of workspace.getLeavesOfType(type) || []) leaves.push(leaf);
        } catch (_error) {
          // Other leaf types are not Markdown editors.
        }
      }
    }
  } catch (_error) {
    return [...touched];
  }
  const dirty = new Set();
  for (const leaf of leaves) {
    const view = leaf && leaf.view;
    const file = view && view.file;
    const editor = view && view.editor;
    if (!file || !touched.has(String(file.path || "")) || !editor || typeof editor.getValue !== "function") continue;
    try {
      const disk = typeof vault.read === "function"
        ? await vault.read(file)
        : vault.adapter && typeof vault.adapter.read === "function"
          ? await vault.adapter.read(file.path)
          : null;
      if (typeof disk !== "string" || String(editor.getValue()) !== disk) dirty.add(file.path);
    } catch (_error) {
      // If an affected buffer cannot be compared with disk, refuse the write.
      dirty.add(file.path);
    }
  }
  return [...dirty].sort();
}

class RelationLabelRenameModal extends Modal {
  constructor(app, from, options = {}) {
    super(app);
    this.from = String(from || "");
    this.afterRename = typeof options.afterRename === "function" ? options.afterRename : null;
    this.renamePreview = null;
    this.previewSignature = "";
    this.renameError = "";
    this.renameApplying = false;
  }

  onOpen() {
    this.contentEl.empty();
    this.modalEl.addClass("bob-cnp-modal");
    this.contentEl.addClass("bob-cnp");
    const header = this.contentEl.createDiv({ cls: "bob-cnp-header" });
    const icon = header.createDiv({ cls: "bob-cnp-header-icon" });
    applyIcon(icon, "pencil");
    const headerText = header.createDiv({ cls: "bob-cnp-header-text" });
    headerText.createDiv({ cls: "bob-cnp-title", text: `Rename ${this.from || "relation"}` });
    headerText.createDiv({ cls: "bob-cnp-subtitle", text: "Previewed rename across every LINKS and LINKED FROM label" });

    const form = this.contentEl.createDiv({ cls: "bob-cnp-rename-form" });
    form.createEl("label", { cls: "bob-cnp-rename-label", text: "New relation label" });
    this.nameInput = form.createEl("input", {
      cls: "bob-cnp-input",
      attr: { type: "text", placeholder: "prompted by", "aria-label": "New relation label" },
    });
    this.mergeToggle = form.createEl("input", {
      cls: "bob-cnp-rename-merge",
      attr: { type: "checkbox", "aria-label": "Merge into an existing relation label" },
    });
    form.createEl("label", { cls: "bob-cnp-rename-label", text: "Allow merging into an existing relation label (--merge)" });
    this.mergeConfirmWrap = form.createDiv({ cls: "bob-cnp-rename-merge-confirm" });
    this.mergeConfirmWrap.style.display = "none";
    this.mergeConfirmToggle = this.mergeConfirmWrap.createEl("input", {
      cls: "bob-cnp-rename-merge",
      attr: { type: "checkbox", "aria-label": "Confirm merging relation labels" },
    });
    this.mergeConfirmWrap.createEl("label", {
      cls: "bob-cnp-rename-label",
      text: "Confirm: combine these relation labels everywhere",
    });

    const buttons = this.contentEl.createDiv({ cls: "bob-cnp-rename-buttons" });
    this.previewButton = buttons.createEl("button", { cls: "bob-cnp-rename-button", text: "Preview" });
    this.applyButton = buttons.createEl("button", { cls: "bob-cnp-rename-button", text: "Rename everywhere" });
    this.applyButton.disabled = true;
    this.previewButton.addEventListener("click", () => void this.previewRename());
    this.applyButton.addEventListener("click", () => void this.applyRename());
    this.nameInput.addEventListener("input", () => this.invalidateRenamePreview());
    this.mergeToggle.addEventListener("change", () => this.invalidateRenamePreview());
    this.mergeConfirmToggle.addEventListener("change", () => this.renderRenamePreview());
    this.nameInput.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        void this.previewRename();
      }
    });
    this.previewEl = this.contentEl.createDiv({ cls: "bob-cnp-results" });
    this.renderRenamePreview();
    window.setTimeout(() => {
      if (this.nameInput && typeof this.nameInput.focus === "function") this.nameInput.focus();
    }, 0);
  }

  renameTarget() {
    return normalizeRelationLabel(String((this.nameInput && this.nameInput.value) || "")) || "";
  }

  renameOptions(dryRun) {
    return {
      dryRun: dryRun === true,
      merge: Boolean(this.mergeToggle && this.mergeToggle.checked),
      via: "bob-navigation-hotkeys",
    };
  }

  invalidateRenamePreview() {
    this.renamePreview = null;
    this.previewSignature = "";
    this.renameError = "";
    if (this.mergeConfirmToggle) this.mergeConfirmToggle.checked = false;
    this.renderRenamePreview();
  }

  async freshRenamePreview() {
    const api = getNavigationRelationLabelsApi(this.app);
    if (!api || typeof api.rename !== "function") {
      return { ok: false, message: "Update Bob Ledger Tools to use relation-label renames." };
    }
    return api.rename(this.from, this.renameTarget(), this.renameOptions(true));
  }

  async refuseDirtyEditors(report) {
    const dirty = await relationLabelDirtyEditorPaths(this.app, report);
    if (!dirty.length) return false;
    const shown = dirty.slice(0, 3).join(", ");
    const more = dirty.length > 3 ? `, +${dirty.length - 3} more` : "";
    this.renameError = `Save or close affected open notes before renaming: ${shown}${more}`;
    this.renamePreview = null;
    this.previewSignature = "";
    return true;
  }

  async previewRename() {
    if (this.renameApplying) return null;
    this.renameError = relationLabelRenameInputError(this.renameTarget());
    if (this.renameError) {
      this.renamePreview = null;
      this.renderRenamePreview();
      return null;
    }
    const saved = await saveActiveRelationLabelEditor(this.app);
    if (!saved.ok) {
      this.renameError = saved.message;
      this.renamePreview = null;
      this.renderRenamePreview();
      return null;
    }
    try {
      const result = await this.freshRenamePreview();
      if (!result || result.ok !== true) {
        this.renameError = (result && result.message) || "Could not preview the relation rename.";
        if (result && result.code === "label_exists") this.renameError += " Enable merge to preview combining them.";
        this.renamePreview = null;
        this.renderRenamePreview();
        return null;
      }
      if (await this.refuseDirtyEditors(result)) {
        this.renderRenamePreview();
        return null;
      }
      this.renamePreview = relationLabelRenameReport(result);
      this.previewSignature = relationLabelRenamePreviewSignature(result);
      this.renameError = "";
      if (this.mergeConfirmToggle) this.mergeConfirmToggle.checked = false;
      this.renderRenamePreview();
      return formatRelationLabelRenamePreview(result);
    } catch (_error) {
      this.renameError = "Could not preview the relation rename.";
      this.renamePreview = null;
      this.renderRenamePreview();
      return null;
    }
  }

  renderRenamePreview() {
    if (!this.previewEl) return;
    this.previewEl.empty();
    if (this.renameError) {
      this.previewEl.createDiv({ cls: "bob-cnp-empty-text", text: this.renameError });
    }
    if (this.renamePreview) {
      const summary = formatRelationLabelRenamePreview(this.renamePreview);
      this.previewEl.createDiv({ cls: "bob-cnp-row-title", text: summary.title });
      for (const line of summary.lines) {
        this.previewEl.createDiv({ cls: "bob-cnp-row-path", text: line });
      }
      for (const note of [summary.stateNote, summary.inverseNote, ...summary.warnings].filter(Boolean)) {
        this.previewEl.createDiv({ cls: "bob-cnp-row-path", text: note });
      }
    } else if (!this.renameError) {
      this.previewEl.createDiv({
        cls: "bob-cnp-empty-text",
        text: "Preview shows the affected notes, links, mirrors, and done/ history before anything writes.",
      });
    }
    const merge = Boolean(this.renamePreview && this.renamePreview.merge === true);
    if (this.mergeConfirmWrap) this.mergeConfirmWrap.style.display = merge ? "flex" : "none";
    if (!merge && this.mergeConfirmToggle) this.mergeConfirmToggle.checked = false;
    if (this.applyButton) {
      this.applyButton.textContent = merge ? "Merge labels everywhere" : "Rename everywhere";
      this.applyButton.disabled = Boolean(this.renameError) || !this.renamePreview || (merge && !this.mergeConfirmToggle.checked);
    }
  }

  async applyRename() {
    if (this.renameApplying || this.renameError || !this.renamePreview) return false;
    const merge = this.renamePreview.merge === true;
    if (merge && !this.mergeConfirmToggle.checked) {
      this.renameError = "Confirm the merge before writing.";
      this.renderRenamePreview();
      return false;
    }
    this.renameApplying = true;
    if (this.applyButton) this.applyButton.disabled = true;
    try {
      const saved = await saveActiveRelationLabelEditor(this.app);
      if (!saved.ok) {
        this.renameError = saved.message;
        this.renderRenamePreview();
        return false;
      }
      const fresh = await this.freshRenamePreview();
      if (!fresh || fresh.ok !== true) {
        this.renameError = (fresh && fresh.message) || "Could not refresh the relation rename preview.";
        this.renderRenamePreview();
        return false;
      }
      if (await this.refuseDirtyEditors(fresh)) {
        this.renderRenamePreview();
        return false;
      }
      const freshSignature = relationLabelRenamePreviewSignature(fresh);
      if (freshSignature !== this.previewSignature) {
        this.renamePreview = relationLabelRenameReport(fresh);
        this.previewSignature = freshSignature;
        if (this.mergeConfirmToggle) this.mergeConfirmToggle.checked = false;
        this.renameError = "The vault changed since this preview. Review the updated plan and confirm again.";
        this.renderRenamePreview();
        return false;
      }
      const api = getNavigationRelationLabelsApi(this.app);
      const result = await api.rename(this.from, this.renameTarget(), this.renameOptions(false));
      if (!result || result.ok !== true) {
        this.renameError = (result && result.message) || "Could not rename the relation label.";
        this.renderRenamePreview();
        return false;
      }
      const summary = formatRelationLabelRenamePreview(result);
      const report = relationLabelRenameReport(result);
      const syncPending = report && report.sync && report.sync.post === "failed" ? " · sync pending" : "";
      new Notice(`Renamed ${this.from} → ${this.renameTarget()} · ${summary.links} ${summary.links === 1 ? "link" : "links"} in ${summary.notes} ${summary.notes === 1 ? "note" : "notes"} · one commit${syncPending}`);
      this.close();
      if (this.afterRename) {
        try {
          await this.afterRename(this.from, this.renameTarget(), result);
        } catch (_error) {
          // The rename committed; refreshing a client view cannot roll it back.
        }
      }
      return true;
    } catch (_error) {
      this.renameError = "Could not rename the relation label.";
      this.renderRenamePreview();
      return false;
    } finally {
      this.renameApplying = false;
      if (this.applyButton) this.applyButton.disabled = Boolean(this.renameError) || !this.renamePreview || (this.renamePreview.merge === true && !this.mergeConfirmToggle.checked);
    }
  }

  onClose() {
    this.modalEl.removeClass("bob-cnp-modal");
    this.contentEl.empty();
  }
}

class RelationLabelActionModal extends FilteredPickerModal {
  constructor(app, manager, row) {
    const label = String(row && row.name || "relation");
    const hidden = row && row.hidden === true;
    super(app, {
      items: [
        { key: "rename", title: `Rename ${label}`, meta: "Preview every changed note (r)" },
        { key: "visibility", title: `${hidden ? "Unhide" : "Hide"} ${label}`, meta: "Changes suggestions only (h)" },
      ],
      title: label,
      headerIcon: "link-2",
      inputLabel: "Choose a relation-label action",
      placeholder: "type to filter · r/h jump when empty",
      resultsLabel: "Relation-label actions",
      emptyText: "No actions",
      footerHints: [
        { keys: ["r", "h"], label: "Jump to action" },
        { keys: ["↵"], label: "Run" },
        { keys: ["esc"], label: "Back" },
      ],
      filterItem: (item, query) => !query || `${item.title} ${item.meta}`.toLowerCase().includes(query),
      renderItem: (item, rowEl, query) => {
        addElementClasses(rowEl, "bob-cnp-task-value-row", "is-relation-label-action");
        const icon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
        applyIcon(icon, item.key === "rename" ? "pencil" : "eye-off");
        const text = rowEl.createDiv({ cls: "bob-cnp-row-text" });
        appendHighlighted(text.createDiv({ cls: "bob-cnp-row-title" }), item.title, query);
        text.createDiv({ cls: "bob-cnp-row-path", text: item.meta });
      },
      closeBeforeOpenItem: true,
      openItem: (item) => this.runAction(item),
    });
    this.manager = manager;
    this.labelRow = row;
  }

  handleKeydown(event) {
    if (this.inputEl && String(this.inputEl.value || "") !== "") {
      super.handleKeydown(event);
      return;
    }
    const key = String(event && event.key || "").toLowerCase();
    if (!event.ctrlKey && !event.metaKey && !event.altKey && ["r", "h"].includes(key)) {
      event.preventDefault();
      event.stopPropagation();
      const index = this.items.findIndex((item) => item.key === (key === "r" ? "rename" : "visibility"));
      if (index >= 0) void this.openItemAtIndex(index);
      return;
    }
    super.handleKeydown(event);
  }

  runAction(item) {
    if (!item || !this.manager) return false;
    if (item.key === "rename") this.manager.openRelationLabelRename(this.labelRow);
    else if (item.key === "visibility") void this.manager.toggleRelationLabel(this.labelRow);
    return true;
  }
}

class RelationLabelManagerModal extends FilteredPickerModal {
  constructor(app, plugin) {
    super(app, {
      items: [],
      title: "Relation labels",
      headerIcon: "link-2",
      inputLabel: "Filter relation labels",
      placeholder: "type to filter labels",
      resultsLabel: "Relation labels",
      emptyText: "No relation labels match",
      footerHints: [
        { keys: ["↵"], label: "manage" },
        { keys: ["esc"], label: "dismiss" },
      ],
      getSubtitle: () => `${this.managerRows.length} labels · Hide changes suggestions only`,
      filterItem: (row, query) => !query || `${row.name} ${row.key} ${row.inverse || ""}`.toLowerCase().includes(query),
      renderItem: (row, rowEl, query) => this.renderRelationLabelRow(row, rowEl, query),
      closeBeforeOpenItem: true,
      openItem: (row) => this.openRelationLabelActions(row),
    });
    this.plugin = plugin;
    this.relationLabelsApi = getNavigationRelationLabelsApi(app);
    this.managerRows = [];
    this.writeInFlight = new Set();
    this.unsubscribeRelationLabels = null;
  }

  onOpen() {
    super.onOpen();
    if (!this.relationLabelsApi || typeof this.relationLabelsApi.rows !== "function") {
      new Notice("Update Bob Ledger Tools to use relation labels.");
      this.close();
      return;
    }
    if (typeof this.relationLabelsApi.onChange === "function") {
      this.unsubscribeRelationLabels = this.relationLabelsApi.onChange(() => {
        void this.refreshRelationLabelManagerRows();
      });
    }
    void this.refreshRelationLabelManagerRows();
  }

  async refreshRelationLabelManagerRows() {
    try {
      const rows = this.relationLabelsApi.rows("", { hidden: "include" });
      if (rows && typeof rows.then === "function") return false;
      if (!Array.isArray(rows)) return false;
      const selected = this.visibleItems && this.visibleItems[this.selectedIndex];
      const selectedKey = selected && selected.key;
      this.managerRows = rows.filter((row) => row && row.name).map((row) => ({
        ...row,
        key: String(row.key || normalizeRelationLabel(row.name).toLowerCase()),
        name: String(row.name),
        hidden: row.hidden === true,
        count: Math.max(0, Math.floor(numericOrDefault(row.count, 0))),
      }));
      this.items = this.managerRows;
      const index = this.managerRows.findIndex((row) => row.key === selectedKey);
      this.selectedIndex = index >= 0 ? index : 0;
      this.renderResults();
      return true;
    } catch (_error) {
      new Notice("Could not load relation labels.");
      return false;
    }
  }

  renderRelationLabelRow(row, rowEl, query) {
    addElementClasses(rowEl, "bob-cnp-task-value-row", "is-relation-label-manager-row", row.hidden ? "is-hidden" : "");
    const icon = rowEl.createDiv({ cls: "bob-cnp-row-icon" });
    applyIcon(icon, row.hidden ? "eye-off" : "link-2");
    const text = rowEl.createDiv({ cls: "bob-cnp-row-text" });
    appendHighlighted(text.createDiv({ cls: "bob-cnp-row-title" }), row.name, query);
    const meta = row.hidden
      ? "hidden from suggestions"
      : `${row.count} ${row.count === 1 ? "link" : "links"}`;
    text.createDiv({ cls: "bob-cnp-row-path", text: row.inverse ? `${meta} · inverse: ${row.inverse}` : meta });
  }

  openRelationLabelActions(row) {
    if (!row) return false;
    new RelationLabelActionModal(this.app, this, row).open();
    return true;
  }

  openRelationLabelRename(row) {
    if (!row || !row.name) return false;
    new RelationLabelRenameModal(this.app, row.name, {
      afterRename: () => this.refreshRelationLabelManagerRows(),
    }).open();
    return true;
  }

  async toggleRelationLabel(row) {
    if (!row || !row.name || this.writeInFlight.has(row.key)) return false;
    const method = row.hidden ? this.relationLabelsApi.unhide : this.relationLabelsApi.hide;
    if (typeof method !== "function") {
      new Notice("Update Bob Ledger Tools to use relation-label writes.");
      return false;
    }
    this.writeInFlight.add(row.key);
    try {
      const result = await method.call(this.relationLabelsApi, row.name);
      if (!result || result.ok !== true) {
        new Notice((result && result.message) || "Could not update the relation label.");
        return false;
      }
      new Notice(`${row.hidden ? "Unhid" : "Hid"} ${row.name} from suggestions.`);
      await this.refreshRelationLabelManagerRows();
      return true;
    } catch (_error) {
      new Notice("Could not update the relation label.");
      return false;
    } finally {
      this.writeInFlight.delete(row.key);
    }
  }

  onClose() {
    if (typeof this.unsubscribeRelationLabels === "function") {
      try {
        this.unsubscribeRelationLabels();
      } catch (_error) {
        // Unsubscribing cannot affect a completed relation-label write.
      }
    }
    this.unsubscribeRelationLabels = null;
    super.onClose();
  }
}

class BulletPropertyPickerRelationLabelManagementMixin extends FilteredPickerModal {
  openRelationLabelRenameForStage(item) {
    if (!item || item.kind !== "relation-label" || item.typed === true || item.plain === true || !item.label) {
      new Notice("Select an existing relation label to rename.");
      return false;
    }
    new RelationLabelRenameModal(this.app, item.label, {
      afterRename: () => {
        if (this.stage !== "relation-label") return;
        this.relationLabelGhosts = new Map();
        this.relationLabelLastQuery = null;
        this.refreshRelationLabelHeader();
        this.renderResults();
      },
    }).open();
    return true;
  }
}

class BobNavigationHotkeysRelationLabelsManagerMixin {
  openRelationLabelsManager() {
    const api = getNavigationRelationLabelsApi(this.app);
    if (!api || typeof api.rows !== "function") {
      new Notice("Update Bob Ledger Tools to use relation labels.");
      return false;
    }
    try {
      new RelationLabelManagerModal(this.app, this).open();
      return true;
    } catch (_error) {
      new Notice("Could not open relation labels.");
      return false;
    }
  }
}
// ---- src/430-picker-vault-batch.js ----
class BulletPropertyPickerVaultBatchMixin extends FilteredPickerModal {
  async prepareVaultBatch(batch) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const live = [];
    for (const snapshot of batch.promptQueue) {
      const targetPath = normalizeVaultRelativePath(
        snapshot.path || ownerPath,
      );
      const files = await this.readVaultStageFiles([targetPath]);
      if (!files) {
        return false;
      }
      if (this.vaultStage && this.vaultStage.files instanceof Map) {
        this.vaultStage.files.set(targetPath, files.get(targetPath));
      }
      if (snapshot.rawLine == null && !snapshot.blockId) {
        const located = locateStageDisplayText(
          files.get(targetPath),
          snapshot.displayText,
        );
        if (!located) {
          snapshot.dead = true;
          live.push(snapshot);
          continue;
        }
        snapshot.line = located.line;
        snapshot.rawLine = located.rawLine;
        if (located.blockId) {
          snapshot.blockId = located.blockId;
          batch.readyAdditions.push(snapshot);
          continue;
        }
      }
      live.push(snapshot);
    }
    batch.promptQueue = live.filter((snapshot) => !snapshot.dead);
    const deadCount = live.filter((snapshot) => snapshot.dead).length;
    if (deadCount > 0) {
      batch.deadPromptCount = (batch.deadPromptCount || 0) + deadCount;
    }
    if (batch.promptQueue.length === 0) {
      this.clearPendingBatch();
      return this.executeVaultDependencyBatch(batch, {
        skippedOther: batch.deadPromptCount || 0,
      });
    }
    this.pendingBatch = batch;
    return this.promptNextBatchBlockId();
  }

  // Open the block-ID prompt for the task at the current queue position. Returns
  // false so the modal stays open while prompts are collected.
  promptNextBatchBlockId() {
    const batch = this.pendingBatch;
    if (!batch) {
      return false;
    }

    const snapshot = batch.promptQueue[batch.promptIndex];
    if (!snapshot) {
      return false;
    }

    this.showBlockIdStage(snapshot, {
      mode: "batch",
      position: batch.promptIndex + 1,
      total: batch.promptQueue.length,
    });
    return false;
  }

  confirmBlockId(item) {
    if (!this.selectedPropertyItem || !this.pendingTask || !item) {
      return false;
    }

    if (!item.valid) {
      return false;
    }

    if (this.blockIdMode === "batch" && this.pendingBatch) {
      return this.confirmBatchBlockId(item);
    }

    if (
      this.blockIdMode === "counted-source" &&
      this.pendingCountedDependency
    ) {
      return this.confirmCountedDependencyBlockId(item);
    }

    if (this.blockIdMode === "vault-single" && this.pendingVaultSingle) {
      return this.confirmVaultSingleBlockId(item);
    }

    if (this.blockIdMode === "vault-counted" && this.pendingVaultCounted) {
      return this.confirmVaultCountedBlockId(item);
    }

    if (this.blockIdMode === "blocks-source" && this.pendingBlocks) {
      return this.confirmBlocksSourceBlockId(item);
    }

    if (this.blockIdMode === "relation-target" && this.pendingRelation) {
      return this.confirmRelationTargetBlockId(item);
    }

    return this.confirmSingleBlockId(item);
  }

  // Single `+ id` for a cross-note row: the confirmed id is written to the
  // target note first (an unused target id is acceptable, a link to an
  // unprepared target is not), then the link commits through the writer.
  async confirmVaultSingleBlockId(item) {
    const pending = this.pendingVaultSingle;
    if (!pending || !item.valid) {
      return false;
    }
    const snapshot = pending.snapshot;
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || ownerPath,
    );
    const files = await this.readVaultStageFiles([targetPath]);
    if (!files) {
      return false;
    }
    const targetContent = files.get(targetPath);
    const validation = validateBlockIdCandidate(item.id, targetContent, {
      reservedIds: pending.reservedIds || new Set(),
    });
    if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
      new Notice(
        validation.message || "That block ID cannot be used in the target note",
      );
      return false;
    }
    const targetLines = String(targetContent).split(/\r?\n/);
    if (
      targetLines[snapshot.line] !== snapshot.rawLine ||
      !isObsidianTaskAtLine(targetContent, snapshot.line, null, targetLines)
    ) {
      return this.refuseDependencyStale();
    }
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLines[snapshot.line],
      validation.id,
      targetPath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const prepared = await this.plugin.prepareDependencyTargetNote(
      targetPath,
      {
        line: snapshot.line,
        from: targetLines[snapshot.line],
        text: updatedLine,
      },
    );
    if (!prepared.ok) {
      new Notice(`⛓ Could not prepare ${targetPath} (${prepared.reason})`);
      return false;
    }
    this.clearPendingBatch();
    const counters = { stale: 0, other: 0 };
    return this.commitVaultRefs(
      [{ path: targetPath, blockId: validation.id }],
      [],
      counters,
    );
  }

  // Counted `+ id` for a cross-note row: one prompt, then the link applies
  // to every source task that is not already linked.
  async confirmVaultCountedBlockId(item) {
    const pending = this.pendingVaultCounted;
    if (!pending || !item.valid) {
      return false;
    }
    const snapshot = pending.snapshot;
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || this.filePath || "",
    );
    const files = await this.readVaultStageFiles([targetPath]);
    if (!files) {
      return false;
    }
    const validation = validateBlockIdCandidate(
      item.id,
      files.get(targetPath),
      { reservedIds: pending.reservedIds || new Set() },
    );
    if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
      new Notice(
        validation.message || "That block ID cannot be used in the target note",
      );
      return false;
    }
    // The planner resolves targets by `^block-id`, so the confirmed id is
    // written to the target before the single commit below runs.
    const targetLines = String(files.get(targetPath)).split(/\r?\n/);
    if (
      targetLines[snapshot.line] !== snapshot.rawLine ||
      !isObsidianTaskAtLine(files.get(targetPath), snapshot.line, null, targetLines)
    ) {
      return this.refuseDependencyStale();
    }
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLines[snapshot.line],
      validation.id,
      targetPath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const prepared = await this.plugin.prepareDependencyTargetNote(
      targetPath,
      {
        line: snapshot.line,
        from: targetLines[snapshot.line],
        text: updatedLine,
      },
    );
    if (!prepared.ok) {
      new Notice(`⛓ Could not prepare ${targetPath} (${prepared.reason})`);
      return false;
    }
    const confirmed = { ...snapshot, blockId: validation.id, preparedId: true };
    this.clearPendingBatch();
    return this.applyVaultCountedDependencyRef(confirmed);
  }

  async confirmCountedDependencyBlockId(item) {
    const dependencyTask = this.pendingCountedDependency;
    if (!dependencyTask || !item.valid) {
      return false;
    }
    const countedConfirmAction = { label: "add 2 prerequisites" };
    const countedConfirmWrite = async () => {
      const applied = await this.plugin.applyCountedLocalTaskDependency(
        this.editor,
        this.cursor,
        this.filePath,
        this.taskSession,
        dependencyTask,
        { confirmedBlockId: item.id },
      );
      if (applied) {
        this.clearPendingBatch();
      }
      return applied;
    };
    if (typeof this.runInboxRoutedCommit === "function") {
      return await this.runInboxRoutedCommit(
        countedConfirmAction,
        countedConfirmWrite,
      );
    }
    return await countedConfirmWrite();
  }

  // Record one confirmed block ID and either advance to the next prompt (modal
  // stays open) or, on the final prompt, run the batch executor and close only
  // when it succeeds.
  async confirmBatchBlockId(item) {
    const batch = this.pendingBatch;
    const snapshot = batch.promptQueue[batch.promptIndex];
    if (!snapshot) {
      return false;
    }

    batch.confirmedById.set(snapshot.line, item.id);
    if (snapshot.markKey !== undefined && snapshot.markKey !== null) {
      batch.confirmedById.set(snapshot.markKey, item.id);
    }
    batch.reservedIds.add(item.id);
    batch.promptIndex += 1;

    if (batch.promptIndex < batch.promptQueue.length) {
      return this.promptNextBatchBlockId();
    }

    // Cross-note and same-note batches both commit asynchronously (stale
    // re-read per target plus target preparation and recovery).
    if (batch.hasVault) {
      return this.executeVaultDependencyBatch(batch).then((applied) => {
        if (applied) {
          this.clearPendingBatch();
        }
        return applied;
      });
    }
    if (await this.executeDependencyBatch(batch)) {
      this.clearPendingBatch();
      return true;
    }

    // Executor aborted (e.g. cursor bullet changed). Leave the modal open with
    // the failure notice already shown; Esc cancels with nothing written.
    return false;
  }

  confirmSingleBlockId(item) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const task = this.pendingTask;
    const targetLine = getEditorLine(this.editor, task.line);
    if (targetLine !== task.rawLine) {
      return this.refuseDependencyStale();
    }
    if (!isObsidianTaskAtLine(this.getEditorContent(), task.line)) {
      new Notice("Selected dependency is no longer a #task checkbox");
      return false;
    }

    // An existing valid `[id::]` is never rewritten (§3); the planner
    // resolves the kept id for the field. Unencodable paths refuse only
    // when the target has no `[id::]` yet. The confirmed id folds into the
    // writer's one transaction below (one Ctrl+Z).
    const updatedLine = applyPromptedBlockIdPreservingLegacyId(
      targetLine,
      item.id,
      this.filePath,
    );
    if (updatedLine === null) {
      new Notice(
        "Dependency not added: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }

    const confirmedIdField = findBulletPropertyField(updatedLine, "id");
    const depValue = confirmedIdField
      ? normalizeBulletPropertyValue(confirmedIdField.value)
      : "";

    const singleConfirmArgs = {
      showNotice: false,
      linkBlockId: item.id,
      filePath: this.filePath,
      pendingTargetLine: {
        line: task.line,
        expected: targetLine,
        text: updatedLine,
      },
    };
    let armed = false;
    try {
      armed =
        typeof this.isInboxRouteArmed === "function" &&
        this.isInboxRouteArmed() === true &&
        typeof this.runInboxRoutedCommit === "function";
    } catch (error) {
      armed = false;
    }
    if (!armed) {
      const linked = this.plugin.setLocalTaskDependency(
        this.editor,
        this.cursor,
        this.selectedPropertyItem.property.name,
        depValue,
        singleConfirmArgs,
      );
      if (!linked) {
        return false;
      }

      new Notice(`Added ^${item.id} + linked dependency + navigation link`);
      return true;
    }
    const singleConfirmAction = { label: "add 1 prerequisite" };
    const singleConfirmWrite = async () => {
      const linked = await this.plugin.setLocalTaskDependency(
        this.editor,
        this.cursor,
        this.selectedPropertyItem.property.name,
        depValue,
        singleConfirmArgs,
      );
      if (!linked) {
        return false;
      }

      new Notice(`Added ^${item.id} + linked dependency + navigation link`);
      return true;
    };
    return this.runInboxRoutedCommit(singleConfirmAction, singleConfirmWrite);
  }

  // Execution phase: re-guard the cursor bullet, apply each target's edits,
  // rewrite the `[dependsOn:: ...]` list once, then reconcile navigation
  // bullets. Target-line edits are single-line replaces, so target indices stay
  // stable; only the nav reconciliation shifts lines and re-reads as it goes.
  async executeDependencyBatchWithoutInboxRoute(batch) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      batch.cursorLineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }

    // Batch Depends-On write through the pure planner: snapshots resolve
    // read-only here, then one gesture commits the line, the field,
    // same-note target ids and status effects in one
    // editor transaction (one Ctrl+Z), with `[fresh:: today]` stamped last.
    const originalContent = String(this.editor.getValue() || "");
    const filePath = normalizeVaultRelativePath(this.filePath || "");
    if (!filePath) {
      new Notice(
        "Dependencies are unavailable: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const removals = batch.removals.slice();
    let skippedStale = 0;
    let skippedOther = 0;
    // Confirmed `+ id` targets are stamped into a working copy first (the
    // planner resolves by `^block-id`), so the single commit below writes
    // the target ids and the link together.
    const workingLines = originalContent.split(/\r?\n/);
    const collectAddition = (snapshot, confirmedId = null) => {
      const targetLine = getEditorLine(this.editor, snapshot.line);
      if (targetLine !== snapshot.rawLine) {
        skippedStale += 1;
        return null;
      }
      if (!isObsidianTaskAtLine(originalContent, snapshot.line)) {
        skippedOther += 1;
        return null;
      }
      if (confirmedId !== null) {
        // Validated against the working copy (an earlier stamp in this
        // batch already landed there), not the batch's reserved set, which
        // already holds this confirmed id.
        const validation = validateBlockIdCandidate(
          confirmedId,
          workingLines.join(originalContent.includes("\r\n") ? "\r\n" : "\n"),
        );
        if (!validation.valid) {
          skippedOther += 1;
          return null;
        }
        if (!tryDependencyId(filePath, confirmedId)) {
          skippedOther += 1;
          return null;
        }
        const stampedLine = applyPromptedBlockIdPreservingLegacyId(
          targetLine,
          confirmedId,
          filePath,
        );
        if (stampedLine === null) {
          skippedOther += 1;
          return null;
        }
        workingLines[snapshot.line] = stampedLine;
        return { blockId: confirmedId };
      }
      const resolved = resolveTargetTaskIdentity(targetLine, {
        promptWhenBlockIdMissing: true,
        filePath,
      });
      if (resolved.needsBlockIdPrompt || !resolved.value) {
        skippedOther += 1;
        return null;
      }
      return { blockId: resolved.linkBlockId };
    };

    const addRefs = [];
    batch.readyAdditions.forEach((snapshot) => {
      const addition = collectAddition(snapshot);
      if (addition) {
        addRefs.push({ path: filePath, blockId: addition.blockId });
      }
    });
    batch.promptQueue.forEach((snapshot) => {
      const confirmedId = batch.confirmedById.get(snapshot.line);
      if (!confirmedId) {
        skippedOther += 1;
        return;
      }
      const addition = collectAddition(snapshot, confirmedId);
      if (addition) {
        addRefs.push({ path: filePath, blockId: addition.blockId });
      }
    });

    // A stale target refuses the whole batch before any write, then reopens
    // the stage fresh — never a partial commit with a skip count.
    if (skippedStale > 0) {
      return this.refuseDependencyStale();
    }

    // Removal marks carry the row's own block id first, then the field
    // value; resolve each to its `^block-id` in this note. Field-only
    // values need no link edit: the planner sets the field from the line,
    // so they fall out on their own.
    const noteLines = originalContent.split(/\r?\n/);
    const removeRefs = [];
    removals.forEach((removal) => {
      const directBlockId = normalizeBulletPropertyValue(removal.blockId || "");
      if (directBlockId) {
        removeRefs.push({ path: filePath, blockId: directBlockId });
        return;
      }
      const candidates = [
        removal.linkBlockId,
        removal.depValue,
        removal.legacyDepValue,
      ]
        .map(normalizeBulletPropertyValue)
        .filter(Boolean);
      for (const candidate of candidates) {
        if (findTaskLineByTrailingBlockId(noteLines, candidate) !== null) {
          removeRefs.push({ path: filePath, blockId: candidate });
          return;
        }
      }
      for (let index = 0; index < noteLines.length; index += 1) {
        if (!isObsidianTaskAtLine(originalContent, index)) {
          continue;
        }
        const idField = findBulletPropertyField(noteLines[index], "id");
        const idValue =
          idField && normalizeBulletPropertyValue(idField.value);
        if (idValue && candidates.includes(idValue)) {
          const blockId = getTrailingBlockId(noteLines[index]);
          if (blockId) {
            removeRefs.push({ path: filePath, blockId });
            return;
          }
        }
      }
    });

    // Cycle guard on the post-batch graph (§6.4): a marked row whose edge
    // closes a cycle back to the dependent refuses before any write, like
    // the vault path above (every added edge leaves the same dependent, so
    // one row alone closes a simple cycle). The single-note graph covers
    // same-note batches; cross-note rows commit through `commitVaultRefs`,
    // which guards the full graph.
    {
      const cursorLines = originalContent.split(/\r?\n/);
      const cursorText = String(cursorLines[this.cursor.line] || "");
      const cursorBlockId = getTrailingBlockId(cursorText);
      const cursorIdField = findBulletPropertyField(cursorText, "id");
      const cursorIdValue =
        cursorIdField && normalizeBulletPropertyValue(cursorIdField.value);
      const batchDependentKey =
        (cursorBlockId && dependencyStageRowKey(filePath, cursorBlockId)) ||
        (cursorIdValue ? `id:${cursorIdValue}` : null) ||
        `${filePath}#line:${this.cursor.line}`;
      const trialNotes = [{ path: filePath, content: originalContent }];
      const trialIndex = indexDependencyStageNotes(trialNotes);
      const trialEdges = collectDependencyStageEdges(trialNotes, trialIndex);
      const trial = new Map();
      for (const [from, targets] of trialEdges) {
        trial.set(from, targets.slice());
      }
      const dropKeys = new Set(
        removeRefs
          .map((ref) => dependencyStageRowKey(ref.path, ref.blockId))
          .filter(Boolean),
      );
      const current = (trial.get(batchDependentKey) || []).filter(
        (key) => !dropKeys.has(key),
      );
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        if (key && !current.includes(key)) {
          current.push(key);
        }
      }
      trial.set(batchDependentKey, current);
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        const cycle =
          key === batchDependentKey
            ? [batchDependentKey]
            : findDependencyStageCycle(trial, batchDependentKey, key);
        if (key && cycle) {
          new Notice(
            `⛓ Could not update dependencies (would create a cycle: ${cycle.length - 1} back-link${cycle.length - 1 === 1 ? "" : "s"})`,
          );
          return false;
        }
      }
    }
    const workingContent = workingLines.join(
      originalContent.includes("\r\n") ? "\r\n" : "\n",
    );
    const registry = await readTasksStatusRegistry(
      this.plugin ? this.plugin.app : null,
    );
    const vaultContents =
      this.plugin &&
      needsDependencyRecoverySnapshot(workingContent, this.cursor.line, removeRefs, false, addRefs)
        ? await this.plugin.readDependencyRecoveryVaultContents(
            filePath,
            workingContent,
          )
        : null;
    const freshnessApi =
      this.plugin && typeof this.plugin.getFreshnessApi === "function"
        ? this.plugin.getFreshnessApi()
        : null;
    // §13.19: the stage batch bypasses the shared transaction, so it reads
    // the descendants up front (lanes) and writes them after its commit.
    const batchSubtreePrep = this.plugin &&
      typeof this.plugin.prepareSubtreeForDependencyPlan === "function"
      ? await this.plugin.prepareSubtreeForDependencyPlan(
          filePath,
          workingContent,
          {
            files: new Map([[filePath, workingContent]]),
            add: addRefs,
            remove: removeRefs,
            today: new Date(),
          },
        )
      : null;
    const plan = planDependencyEdit({
      content: workingContent,
      parentLine: this.cursor.line,
      parentPath: filePath,
      add: addRefs,
      remove: removeRefs,
      files: { [filePath]: workingContent },
      vaultFiles: this.plugin
        ? this.plugin.readDependencyVaultFileList()
        : null,
      resolveLinkpath: this.plugin
        ? this.plugin.dependencyLinkpathResolver()
        : null,
      blocksLinesEnabled: loadBlocksLinesEnabled(),
      ...(batchSubtreePrep && batchSubtreePrep.lanes.length > 0
        ? { projectLaneStatuses: batchSubtreePrep.lanes }
        : {}),
      recovery: {
        registry,
        today: new Date(),
        vaultContents,
        markUnblockedLine: navFreshnessMarkUnblockedLine(freshnessApi),
        ...navNoteScopeFlags(filePath),
      },
    });
    if (!plan.ok) {
      new Notice(dependencyPlanFailureNotice(plan.reason, "update"));
      return false;
    }
    const batchSubtreePlanned = batchSubtreePrep &&
      this.plugin &&
      typeof this.plugin.planSubtreePassForPrjEdit === "function"
      ? await this.plugin.planSubtreePassForPrjEdit(
          filePath,
          workingContent,
          plan.nextContent,
          {
            files: new Map([[filePath, workingContent]]),
            descendantTexts: batchSubtreePrep.texts,
            childrenMap: batchSubtreePrep.childrenMap,
            notePaths: batchSubtreePrep.notePaths,
            today: new Date(),
            registry,
            markUnblockedLine: navFreshnessMarkUnblockedLine(freshnessApi),
          },
        )
      : null;
    const batchSubtreeTargets = batchSubtreePlanned
      ? batchSubtreePlanned.pass.pomodoroTargets || []
      : [];
    let batchPlan = plan;
    if (batchSubtreeTargets.length > 0 && plan.summary && plan.summary.project) {
      batchPlan = {
        ...plan,
        summary: {
          ...plan.summary,
          project: {
            ...plan.summary.project,
            pomodoroTargets: Object.freeze([
              ...(plan.summary.project.pomodoroTargets || []),
              ...batchSubtreeTargets,
            ]),
          },
        },
      };
    }
    // Freshness stamps the dependent's post-plan line: a same-note
    // prerequisite above it can gain a BLOCKS line and shift it. Stamping
    // before the Pomodoro fold keeps the line index valid.
    if (
      batchPlan.changed &&
      Number.isInteger(batchPlan.parentLineNext) &&
      this.plugin &&
      typeof this.plugin.stampDependencyParentLine === "function"
    ) {
      batchPlan = {
        ...batchPlan,
        nextContent: this.plugin.stampDependencyParentLine(
          batchPlan.nextContent,
          batchPlan.parentLineNext,
          undefined,
          undefined,
        ),
      };
    }
    // §13.10: consume the live Pomodoro links of `^prj` and its newly
    // Blocked residents. A cleanup failure is reported, never rolled back.
    let batchCommitContent = batchPlan.nextContent;
    let batchPomodoroPrep = null;
    if (batchPlan.changed && this.plugin) {
      batchPomodoroPrep = await prepareProjectPomodoroCleanup(
        typeof this.plugin.readDeferredPomodoroSnapshot === "function"
          ? (snapshotOptions) =>
              this.plugin.readDeferredPomodoroSnapshot(
                this.plugin.app,
                snapshotOptions,
              )
          : null,
        batchPlan,
        filePath,
        workingContent,
        new Date(),
      );
      if (batchPomodoroPrep.commitContent !== batchPlan.nextContent) {
        batchCommitContent = batchPomodoroPrep.commitContent;
      }
    }
    if (batchPlan.changed) {
      if (!applyEditorContentTransaction(this.editor, originalContent, batchCommitContent, null, BLOCKS_MACHINE_WRITE_ANNOTATION)) {
        new Notice("Could not update bullet property");
        return false;
      }
    }
    // §13.19: descendants land after the dependent's own write; a stale one
    // is skipped and counted, never rolled back.
    let batchSubtree = null;
    if (
      batchPlan.changed &&
      batchSubtreePlanned &&
      this.plugin &&
      typeof this.plugin.writeSubtreePass === "function"
    ) {
      try {
        const wrote = await this.plugin.writeSubtreePass(batchSubtreePlanned.pass);
        batchSubtree = Object.freeze({
          blocked: batchSubtreePlanned.pass.blocked,
          recovered: batchSubtreePlanned.pass.recovered,
          written: wrote.written,
          skipped: wrote.skipped,
        });
      } catch (_error) {
        batchSubtree = null;
      }
    }
    let batchPomodoroRemoved = 0;
    let batchPomodoroPruneFailed = false;
    if (batchPomodoroPrep && this.plugin) {
      const batchDone = await finishProjectPomodoroCleanup(
        typeof this.plugin.writeDeferredPomodoroCleanup === "function"
          ? (snapshot, cleanup) =>
              this.plugin.writeDeferredPomodoroCleanup(snapshot, cleanup)
          : null,
        batchPomodoroPrep.snapshot,
        batchPomodoroPrep.cleanup,
      );
      batchPomodoroRemoved = batchDone.removed;
      batchPomodoroPruneFailed = batchDone.failed;
    }

    const skipped = skippedStale + skippedOther;
    const batchProjectNotice = dependencyPomodoroNotice(
      batchPlan,
      batchPomodoroRemoved,
      batchPomodoroPruneFailed,
    );
    const batchNotice = withSubtreePassNotice(
      batchProjectNotice || batchPlan.notice,
      batchSubtree,
    );
    await this.plugin.finishBlocksFollowUps(
      batchPlan.blocksFollowUps,
      batchNotice + (skipped > 0 ? ` (${skipped} skipped)` : ""),
    );
    return true;
  }

  // Vault-wide single remove: CURRENT rows toggle off through the writer
  // (`docs/task-dependencies.md` §6.6). Removing a link is always allowed,
  // so the target is never re-read; the dependent is guarded by its
  // snapshot line text.
  // A stale target or dependent refuses with `changed — reopen` and then
  // reopens the stage fresh (`docs/task-dependencies.md` §6.4). Best-effort:
  // harness stubs without a picker opener just keep the refusal.
  async executeDependencyBatch(batch) {
    const inboxAction = { label: "add 2 prerequisites" };
    const inboxWrite = async () => await this.executeDependencyBatchWithoutInboxRoute(batch);
    if (typeof this.runInboxRoutedCommit === "function") {
      return await this.runInboxRoutedCommit(inboxAction, inboxWrite);
    }
    return await inboxWrite();
  }
}
// ---- src/440-picker-vault-commit.js ----
class BulletPropertyPickerVaultCommitMixin extends FilteredPickerModal {
  reopenDependencyStageFresh() {
    try {
      const plugin = this.plugin;
      const editor = this.editor;
      if (
        !plugin ||
        !editor ||
        typeof plugin.openBulletPropertyPicker !== "function"
      ) {
        return;
      }
      try {
        this.close();
      } catch (_closeError) {
        // Best-effort close only.
      }
      void plugin.openBulletPropertyPicker(editor, {
        initialProperty: this.blocksStage ? null : "dependsOn",
        reopenBlocksStage: this.blocksStage === true,
        directStage: true,
        inboxRoute: this.inboxRoute || null,
      });
    } catch (_reopenError) {
      // Best-effort reopen only.
    }
  }

  refuseDependencyStale(message = "changed — reopen") {
    new Notice(message);
    this.reopenDependencyStageFresh();
    return false;
  }

  async removeSingleDependency(item) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const blockId = normalizeBulletPropertyValue(
      item.blockId || item.existingBlockId || "",
    );
    if (!ownerPath || !blockId) {
      new Notice("⛓ Could not remove dependency (missing link target)");
      return false;
    }
    const removeAction = { label: "remove 1 prerequisite" };
    const removeWrite = async () => {
      const outcome = await this.plugin.applyDependencyEdit({
        editor: this.editor,
        parentPath: ownerPath,
        parentLine: this.cursor.line,
        add: [],
        remove: [
          { path: normalizeVaultRelativePath(item.path || ownerPath), blockId },
        ],
      });
      if (!outcome.ok) {
        if (outcome.reason === "stale-editor") {
          // `applyDependencyEdit` already showed `changed — reopen`: only
          // reopen the stage fresh, without a second notice (§6.4).
          this.reopenDependencyStageFresh();
          return false;
        }
        new Notice(`⛓ Could not remove dependency (${outcome.reason})`);
        return false;
      }
      new Notice(outcome.notice || "⛓ Dependency removed");
      return true;
    };
    if (typeof this.runInboxRoutedCommit === "function") {
      return await this.runInboxRoutedCommit(removeAction, removeWrite);
    }
    return await removeWrite();
  }

  // Vault-wide single add: re-read the target note and refuse when the
  // target changed since the stage opened, then commit through the writer.
  // Rows without a block id detour through the `+ id` prompt first.
  async chooseVaultTaskDependency(item) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      this.lineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const snapshot = {
      markKey: bulletPropertyTaskMarkKey(item),
      path: normalizeVaultRelativePath(item.path || ownerPath),
      line: item.line,
      rawLine: item.rawLine,
      displayText: item.displayText,
      existingIdField: item.existingIdField || null,
      blockId: item.existingBlockId || null,
    };
    const ownerForSingle = normalizeVaultRelativePath(this.filePath || "");
    const singleTargetPath = normalizeVaultRelativePath(
      snapshot.path || ownerForSingle,
    );
    const singleFiles = await this.readVaultStageFiles([singleTargetPath]);
    if (!singleFiles) {
      return false;
    }
    if (this.vaultStage && this.vaultStage.files instanceof Map) {
      this.vaultStage.files.set(
        singleTargetPath,
        singleFiles.get(singleTargetPath),
      );
    }
    if (!snapshot.blockId && snapshot.rawLine == null) {
      // Cache-only `+ id` row: match the target fresh by display text.
      const located = locateStageDisplayText(
        singleFiles.get(singleTargetPath),
        snapshot.displayText,
      );
      if (!located) {
        return this.refuseDependencyStale();
      }
      snapshot.line = located.line;
      snapshot.rawLine = located.rawLine;
      if (located.blockId) {
        snapshot.blockId = located.blockId;
      }
    }
    if (!snapshot.blockId) {
      this.pendingVaultSingle = { snapshot, reservedIds: new Set() };
      this.showBlockIdStage(snapshot, { mode: "vault-single" });
      return false;
    }
    const files = singleFiles;
    const counters = { stale: 0, other: 0 };
    const addition = this.collectVaultAddition(snapshot, files, counters);
    if (!addition) {
      if (counters.stale > 0) {
        return this.refuseDependencyStale();
      }
      new Notice("Could not identify the selected dependency");
      return false;
    }
    return this.commitVaultRefs([addition], [], counters);
  }

  // Fresh contents for the parent plus every involved target note: stage
  // snapshots first (open buffers win), then a guarded vault read for the
  // rest. Returns null with a notice when an addition target is unreadable:
  // if preparation fails, the dependent is untouched (§6.6).
  async readVaultStageFiles(paths) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const files = new Map();
    if (this.vaultStage && this.vaultStage.files instanceof Map) {
      for (const [path, content] of this.vaultStage.files) {
        files.set(path, String(content || ""));
      }
    }
    files.set(ownerPath, String(this.editor.getValue() || ""));
    for (const rawPath of paths || []) {
      const path = normalizeVaultRelativePath(rawPath || "");
      if (!path) {
        continue;
      }
      // Open buffers win over stage snapshots (a `+ id` pre-write lands in
      // the buffer first); otherwise re-read, so validation and planning
      // see post-open edits.
      const buffered =
        this.plugin && typeof this.plugin.readOpenBufferContent === "function"
          ? this.plugin.readOpenBufferContent(path)
          : null;
      if (buffered !== null) {
        files.set(path, buffered);
        continue;
      }
      if (files.has(path)) {
        continue;
      }
      const loaded = await this.plugin.readDependencyNoteContent(
        path,
        null,
        ownerPath,
      );
      if (loaded === null) {
        new Notice(`⛓ Could not read ${path}; no tasks were updated`);
        return null;
      }
      files.set(path, String(loaded));
    }
    return files;
  }

  // Resolve one vault addition against fresh content: the target must still
  // carry the staged block id on the staged line text, else it is stale.
  // Prompt-queue snapshots (no block id yet) match by line text instead.
  collectVaultAddition(snapshot, files, counters, confirmedId = null) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const targetPath = normalizeVaultRelativePath(
      snapshot.path || ownerPath,
    );
    const targetContent = files.get(targetPath);
    if (targetContent === undefined) {
      counters.other += 1;
      return null;
    }
    const targetLines = String(targetContent).split(/\r?\n/);
    const at = Math.floor(numericOrDefault(snapshot.line, Number.NaN));
    const wantBlockId =
      confirmedId !== null
        ? normalizeBulletPropertyValue(confirmedId)
        : normalizeBulletPropertyValue(snapshot.blockId || "");
    if (confirmedId !== null) {
      const validation = validateBlockIdCandidate(
        confirmedId,
        targetContent,
        { reservedIds: this.getBlockIdReservedIds() },
      );
      if (!validation.valid || !tryDependencyId(targetPath, validation.id)) {
        counters.other += 1;
        return null;
      }
      if (
        !Number.isFinite(at) ||
        targetLines[at] !== snapshot.rawLine ||
        !isObsidianTaskAtLine(targetContent, at, null, targetLines)
      ) {
        counters.stale += 1;
        return null;
      }
      return { path: targetPath, blockId: validation.id };
    }
    if (!wantBlockId) {
      counters.other += 1;
      return null;
    }
    // Just-prepared `+ id` targets — and cache-only rows, which carry no
    // staged line text — resolve by block id with task-ness as the check.
    if (snapshot.preparedId || snapshot.rawLine == null) {
      const placed = findTaskLineByTrailingBlockId(targetLines, wantBlockId);
      if (
        placed === null ||
        !isObsidianTaskAtLine(targetContent, placed, null, targetLines)
      ) {
        counters.stale += 1;
        return null;
      }
      return { path: targetPath, blockId: wantBlockId };
    }
    const found = findTaskLineByTrailingBlockId(targetLines, wantBlockId);
    if (
      found === null ||
      String(targetLines[found] || "") !== String(snapshot.rawLine || "") ||
      !isObsidianTaskAtLine(targetContent, found, null, targetLines)
    ) {
      counters.stale += 1;
      return null;
    }
    return { path: targetPath, blockId: wantBlockId };
  }

  // One vault commit for a whole batch: guards the batch graph for cycles
  // after the whole batch (§6.4), then writes through `applyDependencyEdit`
  // — cross-note targets prepared first, the dependent committed in one
  // editor transaction, with the §6.7 notice.
  async commitVaultRefs(addRefs, removeRefs, counters = { stale: 0, other: 0 }) {
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    const stage = this.vaultStage;
    const dependentKey = stage && stage.dependent ? stage.dependent.key : null;
    if (dependentKey && stage && stage.edges instanceof Map) {
      const trial = new Map();
      for (const [from, targets] of stage.edges) {
        trial.set(from, targets.slice());
      }
      // A `^prj` add implicitly adds resident `→ X` for every open
      // resident (§13.10): trial those edges too, so X depending on a
      // resident is refused.
      const residentKeys =
        stage && stage.dependent && Array.isArray(stage.dependent.projectResidentKeys)
          ? stage.dependent.projectResidentKeys.filter(
              (residentKey) => residentKey && residentKey !== dependentKey,
            )
          : [];
      const dropKeys = new Set(
        removeRefs
          .map((ref) => dependencyStageRowKey(ref.path, ref.blockId))
          .filter(Boolean),
      );
      const current = (trial.get(dependentKey) || []).filter(
        (key) => !dropKeys.has(key),
      );
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        if (key && !current.includes(key)) {
          current.push(key);
        }
        for (const residentKey of residentKeys) {
          const residentTargets = trial.get(residentKey) || [];
          if (key && !residentTargets.includes(key)) {
            residentTargets.push(key);
            trial.set(residentKey, residentTargets);
          }
        }
      }
      trial.set(dependentKey, current);
      for (const ref of addRefs) {
        const key = dependencyStageRowKey(ref.path, ref.blockId);
        let cycle =
          key === dependentKey
            ? [dependentKey]
            : findDependencyStageCycle(trial, dependentKey, key);
        if (!cycle && key) {
          for (const residentKey of residentKeys) {
            cycle = key === residentKey
              ? [residentKey]
              : findDependencyStageCycle(trial, residentKey, key);
            if (cycle) {
              break;
            }
          }
        }
        if (key && cycle) {
          new Notice(
            `⛓ Could not update dependencies (would create a cycle: ${cycle.length - 1} back-link${cycle.length - 1 === 1 ? "" : "s"})`,
          );
          return false;
        }
      }
    }
    const count = (Array.isArray(addRefs) ? addRefs.length : 0) +
      (Array.isArray(removeRefs) ? removeRefs.length : 0);
    const vaultAction = {
      label: count > 1 ? `add ${count} prerequisites` : "edit dependencies",
    };
    const vaultWrite = async () => {
      const outcome = await this.plugin.applyDependencyEdit({
        editor: this.editor,
        parentPath: ownerPath,
        parentLine: this.cursor.line,
        add: addRefs,
        remove: removeRefs,
      });
      if (!outcome.ok) {
        // A stale write refuses and reopens the stage fresh, exactly like the
        // same-note `executeDependencyBatch` (§6.4). `applyDependencyEdit`
        // already showed `changed — reopen`, so only reopen here.
        if (outcome.reason === "stale-editor") {
          this.reopenDependencyStageFresh();
          return false;
        }
        new Notice(dependencyPlanFailureNotice(outcome.reason, "update"));
        return false;
      }
      const skipped = (counters.stale || 0) + (counters.other || 0);
      new Notice(
        (outcome.notice || "⛓ Dependencies updated") +
          (skipped > 0 ? ` (${skipped} skipped)` : ""),
      );
      return true;
    };
    if (typeof this.runInboxRoutedCommit === "function") {
      return await this.runInboxRoutedCommit(vaultAction, vaultWrite);
    }
    return await vaultWrite();
  }

  // Batch executor for stages containing cross-note rows: every target is
  // re-read fresh (a stale row refuses the whole batch before any write),
  // `+ id` prompts were collected up front, and the whole batch commits
  // once.
  async executeVaultDependencyBatchWithoutInboxRoute(batch, seedCounters = null) {
    const parentValidation = validateDependencyParentForEditor(
      this.editor,
      this.cursor,
      batch.cursorLineText,
    );
    if (!parentValidation.valid) {
      new Notice(parentValidation.message);
      return false;
    }
    const ownerPath = normalizeVaultRelativePath(this.filePath || "");
    if (!ownerPath) {
      new Notice(
        "Dependencies are unavailable: this note path cannot be encoded as a dependency ID",
      );
      return false;
    }
    const targetPaths = new Set();
    for (const snapshot of [...batch.readyAdditions, ...batch.promptQueue]) {
      targetPaths.add(normalizeVaultRelativePath(snapshot.path || ownerPath));
    }
    const files = await this.readVaultStageFiles([...targetPaths]);
    if (!files) {
      return false;
    }
    const counters = {
      stale: (seedCounters && seedCounters.stale) || 0,
      other: (seedCounters && seedCounters.skippedOther) || 0,
    };
    const addRefs = [];
    for (const snapshot of batch.readyAdditions) {
      const addition = this.collectVaultAddition(snapshot, files, counters);
      if (addition) {
        addRefs.push(addition);
      }
    }
    // A stale row refuses the whole batch before any write, then reopens
    // the stage fresh — never a partial commit with a skip count — exactly
    // like the same-note `executeDependencyBatch` (§6.4).
    if (counters.stale > 0) {
      return this.refuseDependencyStale();
    }
    // Prompt-queue targets validate before any `+ id` preparation writes:
    // a stale prompt row below refuses with nothing written, even when an
    // earlier target already validated.
    const pendingPreparations = [];
    for (const snapshot of batch.promptQueue) {
      const key = snapshot.markKey !== undefined && snapshot.markKey !== null
        ? snapshot.markKey
        : snapshot.line;
      const confirmedId = batch.confirmedById.get(key);
      if (!confirmedId) {
        counters.other += 1;
        continue;
      }
      const addition = this.collectVaultAddition(
        snapshot,
        files,
        counters,
        confirmedId,
      );
      if (!addition) {
        continue;
      }
      // The planner resolves targets by `^block-id`, so the confirmed id is
      // written to the target first (open editor, else a preimage-checked
      // vault update). If preparation fails the dependent is untouched.
      const targetPath = normalizeVaultRelativePath(
        snapshot.path || ownerPath,
      );
      const freshContent = files.get(targetPath);
      const freshLines = String(freshContent).split(/\r?\n/);
      const updatedLine = applyPromptedBlockIdPreservingLegacyId(
        freshLines[snapshot.line],
        addition.blockId,
        targetPath,
      );
      if (updatedLine === null) {
        counters.other += 1;
        continue;
      }
      pendingPreparations.push({
        snapshot,
        addition,
        targetPath,
        from: freshLines[snapshot.line],
        text: updatedLine,
      });
    }
    if (counters.stale > 0) {
      return this.refuseDependencyStale();
    }
    for (const preparation of pendingPreparations) {
      const prepared = await this.plugin.prepareDependencyTargetNote(
        preparation.targetPath,
        {
          line: preparation.snapshot.line,
          from: preparation.from,
          text: preparation.text,
        },
      );
      if (!prepared.ok) {
        new Notice(
          `⛓ Could not prepare ${preparation.targetPath} (${prepared.reason}); no tasks were updated`,
        );
        return false;
      }
      addRefs.push(preparation.addition);
    }
    // Removal marks carry the row's own block id first; cross-note
    // removals resolve through the staged block id, same-note removals
    // through that id then the existing note scan. Field-only values need
    // no link edit: the planner sets the field from the line, so they fall
    // out on their own.
    const noteLines = String(this.editor.getValue() || "").split(/\r?\n/);
    const removeRefs = [];
    for (const removal of batch.removals) {
      const removalPath = normalizeVaultRelativePath(
        removal.path || ownerPath,
      );
      if (removalPath !== ownerPath) {
        if (normalizeBulletPropertyValue(removal.blockId || "")) {
          removeRefs.push({ path: removalPath, blockId: removal.blockId });
        } else {
          counters.other += 1;
        }
        continue;
      }
      const directBlockId = normalizeBulletPropertyValue(removal.blockId || "");
      if (directBlockId) {
        removeRefs.push({ path: ownerPath, blockId: directBlockId });
        continue;
      }
      const candidates = [
        removal.linkBlockId,
        removal.depValue,
        removal.legacyDepValue,
      ]
        .map(normalizeBulletPropertyValue)
        .filter(Boolean);
      let resolved = null;
      for (const candidate of candidates) {
        if (findTaskLineByTrailingBlockId(noteLines, candidate) !== null) {
          resolved = candidate;
          break;
        }
      }
      if (!resolved) {
        for (let index = 0; index < noteLines.length; index += 1) {
          if (!isObsidianTaskAtLine(String(this.editor.getValue() || ""), index)) {
            continue;
          }
          const idField = findBulletPropertyField(noteLines[index], "id");
          const idValue = idField && normalizeBulletPropertyValue(idField.value);
          if (idValue && candidates.includes(idValue)) {
            const blockId = getTrailingBlockId(noteLines[index]);
            if (blockId) {
              resolved = blockId;
              break;
            }
          }
        }
      }
      if (resolved) {
        removeRefs.push({ path: ownerPath, blockId: resolved });
      }
    }
    if (addRefs.length === 0 && removeRefs.length === 0) {
      const skipped = counters.stale + counters.other;
      new Notice(
        skipped > 0
          ? `No dependencies changed (${skipped} skipped)`
          : "No dependencies changed",
      );
      return false;
    }
    return this.commitVaultRefs(addRefs, removeRefs, counters);
  }

  hasCountedRollBatchForDateProperty(datePropertyName) {
    if (!this.isCountedSession()) {
      return false;
    }
    const batch = this.getCountedRollBatchForDateProperty(datePropertyName);
    if (!batch) {
      return false;
    }
    return (
      batch.actionableCount > 0 || Boolean(batch.unavailableReason)
    );
  }

  async applyCountedRecommendedRoll() {
    const cached = this.countedRollBatch;
    if (!cached) {
      return false;
    }
    if (cached.unavailableReason) {
      new Notice(cached.unavailableReason);
      return false;
    }
    if (this.opening) {
      return false;
    }
    this.opening = true;
    try {
      const fresh = this.computeCountedRollBatch();
      if (
        !fresh ||
        fresh.actionableCount !== cached.actionableCount ||
        fresh.counts.roll !== cached.counts.roll ||
        fresh.counts.decay !== cached.counts.decay ||
        fresh.counts.cancel !== cached.counts.cancel ||
        Boolean(fresh.unavailableReason) !==
          Boolean(cached.unavailableReason)
      ) {
        new Notice("Task changed while the picker was open; nothing was written");
        this.countedRollBatch = fresh;
        this.countedRollBatchReady = true;
        this.returnHome({ rebuild: true });
        return false;
      }
      return await this.maybeOfferCountedRecommendedWorkLog(cached);
    } finally {
      this.opening = false;
    }
  }

  describeInboxRouteCountedRollAction(cached) {
    try {
      const count =
        cached && Number.isInteger(cached.actionableCount)
          ? cached.actionableCount
          : 0;
      return {
        label:
          count > 1 ? `apply ${count} rolls` : "apply recommendation",
      };
    } catch (error) {
      return { label: "apply recommendation" };
    }
  }

  async maybeOfferCountedRecommendedWorkLog(cached) {
    const entries = Array.isArray(cached.entries) ? cached.entries : [];
    const schedulingEntries = entries.filter(
      (entry) =>
        entry &&
        entry.recommendation &&
        (entry.recommendation.kind === "roll" ||
          entry.recommendation.kind === "decay"),
    );
    const countedAction = this.describeInboxRouteCountedRollAction(cached);
    const runCountedRoll = async (schedulingWorkLog) =>
      await this.plugin.applyCountedRecommendedRoll(this, {
        schedulingWorkLog: schedulingWorkLog || null,
      });
    const runRoutedCountedRoll = async (schedulingWorkLog) => {
      if (typeof this.runInboxRoutedCommit === "function") {
        return await this.runInboxRoutedCommit(countedAction, () =>
          runCountedRoll(schedulingWorkLog),
        );
      }
      return await runCountedRoll(schedulingWorkLog);
    };
    if (schedulingEntries.length === 0) {
      return await runRoutedCountedRoll(null);
    }
    const targets = schedulingEntries.map((entry) => ({
      line: entry.line,
      rawLine: entry.rawLine,
    }));
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      return await runRoutedCountedRoll(null);
    }
    const dates = schedulingEntries
      .map((entry) => entry.recommendation && entry.recommendation.date)
      .filter(Boolean);
    const scheduleSummary = formatSchedulingWorkLogDateSpan(dates);
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await runRoutedCountedRoll(
          summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        ),
    });
  }

  async applyLinkRecommendedRoll() {
    const cached = this.linkRollBatch;
    if (!cached) {
      return false;
    }
    if (cached.unavailableReason) {
      new Notice(cached.unavailableReason);
      return false;
    }
    if (this.opening) {
      return false;
    }
    this.opening = true;
    try {
      const fresh = this.computeLinkRollBatch();
      if (
        !fresh ||
        fresh.actionableCount !== cached.actionableCount ||
        fresh.counts.roll !== cached.counts.roll ||
        fresh.counts.decay !== cached.counts.decay ||
        fresh.counts.cancel !== cached.counts.cancel ||
        Boolean(fresh.unavailableReason) !==
          Boolean(cached.unavailableReason)
      ) {
        new Notice("Task changed while the picker was open; nothing was written");
        this.linkRollBatch = fresh;
        this.linkRollBatchReady = true;
        this.returnHome({ rebuild: true });
        return false;
      }
      return await this.maybeOfferLinkRecommendedWorkLog(cached);
    } finally {
      this.opening = false;
    }
  }

  async maybeOfferLinkRecommendedWorkLog(cached) {
    const entries = Array.isArray(cached.entries) ? cached.entries : [];
    const schedulingEntries = entries.filter(
      (entry) =>
        entry &&
        entry.recommendation &&
        (entry.recommendation.kind === "roll" ||
          entry.recommendation.kind === "decay"),
    );
    if (schedulingEntries.length === 0) {
      return await this.plugin.applyLinkRecommendedRoll(this);
    }
    const targets = schedulingEntries.map((entry) => ({
      line: entry.line,
      rawLine: entry.rawLine,
      path: entry.path,
    }));
    const eligible = collectSchedulingWorkLogEligibleOriginalLines(targets);
    if (eligible.size === 0) {
      return await this.plugin.applyLinkRecommendedRoll(this);
    }
    const dates = schedulingEntries
      .map((entry) => entry.recommendation && entry.recommendation.date)
      .filter(Boolean);
    const scheduleSummary = formatSchedulingWorkLogDateSpan(dates);
    // Writers resolve per-note groups and deduplicate repeated links by
    // note and task identity so each qualifying task receives at most one
    // entry; the prompt names the qualifying count for the scheduling subset.
    return await this.offerSchedulingWorkLogOrDispatch({
      targets,
      scheduleSummary,
      dispatch: async (summary) =>
        await this.plugin.applyLinkRecommendedRoll(this, {
          schedulingWorkLog: summary
            ? {
                summary,
                dateText: formatBulletPropertyDate(
                  this.valueBaseDate instanceof Date
                    ? this.valueBaseDate
                    : getLocalDateStart(new Date()),
                ),
              }
            : null,
        }),
    });
  }

  async executeVaultDependencyBatch(batch, seedCounters = null) {
    const inboxAction = { label: "add 2 prerequisites" };
    const inboxWrite = async () => await this.executeVaultDependencyBatchWithoutInboxRoute(batch, seedCounters);
    if (typeof this.runInboxRoutedCommit === "function") {
      return await this.runInboxRoutedCommit(inboxAction, inboxWrite);
    }
    return await inboxWrite();
  }
}
