      window.CodeMirrorAdapter &&
      window.CodeMirrorAdapter.Vim;
    if (!cm || !vim || typeof vim.handleEx !== "function") {
      return false;
    }

    if (this.handledClearSearchHighlightEvents) {
      this.handledClearSearchHighlightEvents.add(event);
    }

